// ─────────────────────────────────────────────────────────────────────────────
// CyberMeters Scan API — Cloudflare Worker
// ─────────────────────────────────────────────────────────────────────────────

// ── Utilities ────────────────────────────────────────────────────────────────

function createId(prefix) {
  return `${prefix}_${crypto.randomUUID()}`;
}

function isValidDomain(domain) {
  if (typeof domain !== "string" || domain.length > 253) return false;
  const labels = domain.split(".");
  if (labels.length < 2 || !/^[a-zA-Z]{2,63}$/.test(labels.at(-1) || "")) return false;
  return labels.every((label) =>
    label.length >= 1 &&
    label.length <= 63 &&
    /^[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?$/.test(label)
  );
}

function isValidEmail(email) {
  if (typeof email !== "string") return false;
  const value = email.trim();
  return value.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function parseBoundedInteger(value, fallback, min, max) {
  const parsed = Number.parseInt(value ?? "", 10);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.min(max, Math.max(min, parsed));
}

function customerSafeFailure(context, error, message) {
  console.error(`[${context}]`, error);
  return message;
}

function validateFrontendRedirectUrl(value, env) {
  if (typeof value !== "string" || !value.trim()) return null;
  try {
    const parsed = new URL(value.trim());
    const configuredFrontend = new URL(
      env.FRONTEND_URL || env.ALLOWED_ORIGIN || "https://app.cybermeters.com"
    );
    if (parsed.protocol !== "https:" || parsed.origin !== configuredFrontend.origin) return null;
    return parsed.toString();
  } catch {
    return null;
  }
}

// ── Auth Crypto Helpers ────────────────────────────────────────────────────────

/**
 * Hash a password using PBKDF2-SHA256 (100,000 iterations).
 * Returns a storable string: "pbkdf2:sha256:100000:<salt_hex>:<hash_hex>"
 */
async function hashPassword(password) {
  const encoder     = new TextEncoder();
  const salt        = crypto.getRandomValues(new Uint8Array(16));
  const keyMaterial = await crypto.subtle.importKey(
    "raw", encoder.encode(password), "PBKDF2", false, ["deriveBits"]
  );
  const hashBits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", hash: "SHA-256", salt, iterations: 100_000 },
    keyMaterial, 256
  );
  const toHex = (buf) => Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, "0")).join("");
  return `pbkdf2:sha256:100000:${toHex(salt.buffer)}:${toHex(hashBits)}`;
}

/**
 * Verify a password against a stored PBKDF2 hash.
 * Uses constant-time XOR comparison to prevent timing attacks.
 */
async function verifyPassword(password, stored) {
  const parts = stored.split(":");
  if (parts.length !== 5 || parts[0] !== "pbkdf2" || parts[1] !== "sha256") return false;
  const iterations  = parseInt(parts[2], 10);
  const saltBytes   = new Uint8Array(parts[3].match(/../g).map(h => parseInt(h, 16)));
  const storedHash  = parts[4];
  const encoder     = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey(
    "raw", encoder.encode(password), "PBKDF2", false, ["deriveBits"]
  );
  const hashBits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", hash: "SHA-256", salt: saltBytes, iterations },
    keyMaterial, 256
  );
  const computed = Array.from(new Uint8Array(hashBits)).map(b => b.toString(16).padStart(2, "0")).join("");
  // Constant-time string comparison
  if (computed.length !== storedHash.length) return false;
  let diff = 0;
  for (let i = 0; i < computed.length; i++) {
    diff |= computed.charCodeAt(i) ^ storedHash.charCodeAt(i);
  }
  return diff === 0;
}

/**
 * Generate a 64-char hex bearer token and return both the raw token (for client)
 * and its SHA-256 hash (for D1 storage — raw token never persisted).
 */
async function generateSessionToken() {
  const raw     = Array.from(crypto.getRandomValues(new Uint8Array(32))).map(b => b.toString(16).padStart(2, "0")).join("");
  const hashBuf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(raw));
  const hash    = Array.from(new Uint8Array(hashBuf)).map(b => b.toString(16).padStart(2, "0")).join("");
  return { raw, hash };
}

async function generateApiToken() {
  const secret = Array.from(crypto.getRandomValues(new Uint8Array(32))).map(b => b.toString(16).padStart(2, "0")).join("");
  const raw    = `cm_${secret}`;
  const hash   = await hashToken(raw);
  return { raw, hash };
}

async function generateInviteToken() {
  const secret = Array.from(crypto.getRandomValues(new Uint8Array(32))).map(b => b.toString(16).padStart(2, "0")).join("");
  const raw    = `cmi_${secret}`;
  const hash   = await hashToken(raw);
  return { raw, hash };
}

/**
 * generateVerificationToken — creates a 64-char hex token for email verification.
 * The raw token is only sent by email. D1 stores its SHA-256 hash.
 */
function generateVerificationToken() {
  return Array.from(crypto.getRandomValues(new Uint8Array(32)))
    .map(b => b.toString(16).padStart(2, "0"))
    .join("");
}

async function generateEmailVerificationToken() {
  const raw = generateVerificationToken();
  const hash = await hashToken(raw);
  return { raw, hash };
}

function getEmailVerificationTokenStatus(userRow, nowMs = Date.now()) {
  if (!userRow) return "invalid";
  if (userRow.email_verified) return "already_verified";
  const expiresAt = Date.parse(userRow.verification_token_expires_at || "");
  if (!Number.isFinite(expiresAt) || expiresAt <= nowMs) return "expired";
  return "valid";
}

function isEmailVerificationResendCoolingDown(expiresAt, nowMs = Date.now()) {
  const expiresAtMs = Date.parse(expiresAt || "");
  const cooldownThreshold = nowMs + (24 * 60 * 60 * 1000) - (60 * 1000);
  return Number.isFinite(expiresAtMs) && expiresAtMs > cooldownThreshold;
}

// ── Microsoft Entra OAuth helpers ────────────────────────────────────────────

/** Decode a base64url string to a UTF-8 string (safe for JWT header/payload). */
function b64urlDecode(str) {
  const base64 = str.replace(/-/g, "+").replace(/_/g, "/");
  const padded  = base64 + "==".slice(0, (4 - (base64.length % 4)) % 4);
  return atob(padded);
}

/** Decode a base64url string to an ArrayBuffer (used for JWT signature). */
function b64urlToBuffer(str) {
  const binary = b64urlDecode(str);
  const buf    = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) buf[i] = binary.charCodeAt(i);
  return buf.buffer;
}

/**
 * Validate a Microsoft Entra id_token (RS256 JWT).
 * Fetches the tenant JWKS, verifies the signature, and validates core claims.
 * Returns the decoded payload on success; throws on any validation failure.
 */
function validateMicrosoftIdTokenClaims(header, payload, clientId, tenantId, expectedNonce = null, nowSeconds = Date.now() / 1000) {
  if (header.alg !== "RS256") throw new Error("id_token: unsupported signing algorithm");
  if (!header.kid) throw new Error("id_token: missing kid");
  if (payload.aud !== clientId) throw new Error("id_token: aud mismatch");
  if (!Number.isFinite(payload.exp) || nowSeconds > payload.exp + 60) throw new Error("id_token: expired");
  if (Number.isFinite(payload.nbf) && nowSeconds + 60 < payload.nbf) throw new Error("id_token: not active");
  if (!payload.oid) throw new Error("id_token: missing oid claim");
  if (!payload.tid) throw new Error("id_token: missing tid claim");

  const multiTenantAliases = new Set(["common", "organizations", "consumers"]);
  if (!multiTenantAliases.has(tenantId) && payload.tid !== tenantId) {
    throw new Error("id_token: tenant mismatch");
  }
  const expectedIssuer = `https://login.microsoftonline.com/${payload.tid}/v2.0`;
  if (payload.iss !== expectedIssuer) throw new Error("id_token: issuer mismatch");
  if (expectedNonce && payload.nonce !== expectedNonce) throw new Error("id_token: nonce mismatch");
}

async function validateMicrosoftIdToken(idToken, clientId, tenantId, expectedNonce = null) {
  const parts = idToken.split(".");
  if (parts.length !== 3) throw new Error("id_token: invalid format");

  const header  = JSON.parse(b64urlDecode(parts[0]));
  const payload = JSON.parse(b64urlDecode(parts[1]));

  validateMicrosoftIdTokenClaims(header, payload, clientId, tenantId, expectedNonce);

  // Fetch signing keys from Microsoft's tenant JWKS endpoint
  const jwksUrl = `https://login.microsoftonline.com/${tenantId}/discovery/v2.0/keys`;
  const jwksRes = await fetch(jwksUrl, { headers: { "User-Agent": "CyberMeters/1.0" } });
  if (!jwksRes.ok) throw new Error(`id_token: JWKS fetch failed (${jwksRes.status})`);
  const { keys } = await jwksRes.json();

  const key = keys.find(k => k.kid === header.kid && (!k.alg || k.alg === "RS256") && (!k.use || k.use === "sig"));
  if (!key) throw new Error("id_token: no matching JWKS key for kid=" + header.kid);

  // Import the RSA public key and verify the RS256 signature
  const cryptoKey = await crypto.subtle.importKey(
    "jwk", key,
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
    false,
    ["verify"]
  );

  const signingInput = new TextEncoder().encode(`${parts[0]}.${parts[1]}`);
  const signature    = b64urlToBuffer(parts[2]);

  const valid = await crypto.subtle.verify("RSASSA-PKCS1-v1_5", cryptoKey, signature, signingInput);
  if (!valid) throw new Error("id_token: signature invalid");

  return payload; // { oid, email, name, tid, sub, ... }
}

// ─────────────────────────────────────────────────────────────────────────────

async function generatePasswordResetToken() {
  const secret = Array.from(crypto.getRandomValues(new Uint8Array(32))).map(b => b.toString(16).padStart(2, "0")).join("");
  const raw    = `cmreset_${secret}`;
  const hash   = await hashToken(raw);
  return { raw, hash };
}

async function generateMfaChallengeToken() {
  const secret = Array.from(crypto.getRandomValues(new Uint8Array(32))).map(b => b.toString(16).padStart(2, "0")).join("");
  const raw    = `cmfa_${secret}`;
  const hash   = await hashToken(raw);
  return { raw, hash };
}

// ── TOTP Engine (RFC 6238) ────────────────────────────────────────────────────
// Pure WebCrypto — no third-party libraries.
// TOTP = HOTP(key, T) where T = floor(unix_seconds / 30)
// HOTP uses HMAC-SHA1 per RFC 4226.

const BASE32_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

function base32Encode(buf) {
  const bytes = new Uint8Array(buf);
  let bits = 0, value = 0, output = "";
  for (const byte of bytes) {
    value = (value << 8) | byte;
    bits += 8;
    while (bits >= 5) {
      output += BASE32_CHARS[(value >>> (bits - 5)) & 0x1f];
      bits -= 5;
    }
  }
  if (bits > 0) output += BASE32_CHARS[(value << (5 - bits)) & 0x1f];
  return output;
}

function base32Decode(str) {
  const clean = str.toUpperCase().replace(/[=\s]/g, "");
  let bits = 0, value = 0;
  const output = [];
  for (const char of clean) {
    const idx = BASE32_CHARS.indexOf(char);
    if (idx < 0) throw new Error(`Invalid base32 character: ${char}`);
    value = (value << 5) | idx;
    bits += 5;
    if (bits >= 8) {
      output.push((value >>> (bits - 8)) & 0xff);
      bits -= 8;
    }
  }
  return new Uint8Array(output);
}

function generateTotpSecret() {
  // 20 bytes = 160-bit secret (RFC 4226 recommended minimum)
  return base32Encode(crypto.getRandomValues(new Uint8Array(20)));
}

async function computeTotp(base32Secret, timeStep = null) {
  const keyBytes = base32Decode(base32Secret);
  const t = timeStep ?? Math.floor(Date.now() / 1000 / 30);

  // 8-byte big-endian counter
  const msg = new DataView(new ArrayBuffer(8));
  const high = Math.floor(t / 0x100000000);
  const low  = t >>> 0;
  msg.setUint32(0, high, false);
  msg.setUint32(4, low,  false);

  const key = await crypto.subtle.importKey(
    "raw", keyBytes, { name: "HMAC", hash: "SHA-1" }, false, ["sign"]
  );
  const sig = new Uint8Array(await crypto.subtle.sign("HMAC", key, msg.buffer));

  // Dynamic truncation (RFC 4226 §5.4)
  const offset = sig[sig.length - 1] & 0x0f;
  const code = (
    ((sig[offset]     & 0x7f) << 24) |
    ((sig[offset + 1] & 0xff) << 16) |
    ((sig[offset + 2] & 0xff) <<  8) |
     (sig[offset + 3] & 0xff)
  ) % 1_000_000;

  return code.toString().padStart(6, "0");
}

async function verifyTotp(base32Secret, code) {
  if (!code || !/^\d{6}$/.test(code.trim())) return false;
  const t = Math.floor(Date.now() / 1000 / 30);
  // Allow ±1 window (30 seconds each side) for clock drift
  for (const delta of [0, -1, 1]) {
    if (await computeTotp(base32Secret, t + delta) === code.trim()) return true;
  }
  return false;
}

// ── MFA secret encryption (AES-256-GCM) ──────────────────────────────────────
// TOTP secrets must be reversible — encrypted with env.MFA_ENCRYPTION_KEY.
// Key derivation: PBKDF2-SHA256, 100k iterations, static purpose-salt.

async function getMfaEncryptionKey(env) {
  if (!env.MFA_ENCRYPTION_KEY) throw new Error("MFA_ENCRYPTION_KEY is not configured");
  const raw     = new TextEncoder().encode(env.MFA_ENCRYPTION_KEY);
  const baseKey = await crypto.subtle.importKey("raw", raw, "PBKDF2", false, ["deriveKey"]);
  return crypto.subtle.deriveKey(
    { name: "PBKDF2", hash: "SHA-256",
      salt: new TextEncoder().encode("cybermeters-mfa-v1"), iterations: 100_000 },
    baseKey,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

async function encryptTotpSecret(base32Secret, env) {
  const key = await getMfaEncryptionKey(env);
  const iv  = crypto.getRandomValues(new Uint8Array(12));
  const ct  = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(base32Secret));
  const toHex = (buf) => Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, "0")).join("");
  return JSON.stringify({ iv: toHex(iv.buffer), ct: toHex(ct) });
}

async function decryptTotpSecret(stored, env) {
  const key = await getMfaEncryptionKey(env);
  const { iv: ivHex, ct: ctHex } = JSON.parse(stored);
  const fromHex = (hex) => new Uint8Array(hex.match(/../g).map(h => parseInt(h, 16)));
  const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: fromHex(ivHex) }, key, fromHex(ctHex));
  return new TextDecoder().decode(plain);
}

// ── Recovery codes ────────────────────────────────────────────────────────────
// 8 codes, format: XXXX-XXXX-XXXX (uppercase alphanumeric).
// Raw codes are shown to user once; PBKDF2 hashes stored in JSON array.

function generateRawRecoveryCode() {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  const bytes = crypto.getRandomValues(new Uint8Array(12));
  const parts = [];
  for (let i = 0; i < 3; i++) {
    let seg = "";
    for (let j = 0; j < 4; j++) seg += chars[bytes[i * 4 + j] % chars.length];
    parts.push(seg);
  }
  return parts.join("-");
}

function normalizeRecoveryCode(code) {
  return code.replace(/-/g, "").toUpperCase().trim();
}

async function generateRecoveryCodes() {
  const codes  = Array.from({ length: 8 }, generateRawRecoveryCode);
  const hashes = await Promise.all(codes.map(c => hashPassword(normalizeRecoveryCode(c))));
  return { codes, hashes };
}

async function verifyRecoveryCode(submittedCode, hashesJson) {
  if (!hashesJson) return { valid: false, remainingHashes: null };
  const hashes     = JSON.parse(hashesJson);
  const normalized = normalizeRecoveryCode(submittedCode);
  for (let i = 0; i < hashes.length; i++) {
    if (await verifyPassword(normalized, hashes[i])) {
      const remaining = hashes.filter((_, idx) => idx !== i);
      return { valid: true, remainingHashes: remaining };
    }
  }
  return { valid: false, remainingHashes: null };
}

/**
 * Hash a bearer token string for D1 lookup (same as above but for incoming tokens).
 */
async function hashToken(raw) {
  const hashBuf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(raw));
  return Array.from(new Uint8Array(hashBuf)).map(b => b.toString(16).padStart(2, "0")).join("");
}

/**
 * requireAuth — unified Bearer-token authentication.
 *
 * Accepts both user sessions and API tokens transparently:
 *   - cm_<secret>  → api_tokens table lookup; returns user + token_scope + token_workspace_id
 *   - anything else → user_sessions table lookup; token_scope/token_workspace_id are undefined
 *
 * All existing call sites receive token auth with zero changes because
 * requireWorkspaceAccess and requireWorkspaceRole enforce scope + workspace binding
 * whenever token_scope is present on the resolved identity.
 */
async function requireAuth(request, env) {
  const authHeader = request.headers.get("Authorization") || "";
  if (!authHeader.startsWith("Bearer ")) return null;
  const rawToken = authHeader.slice(7).trim();
  if (!rawToken) return null;
  try {
    const tokenHash = await hashToken(rawToken);

    // ── API Token path (cm_ prefix) ──────────────────────────────────────────
    if (rawToken.startsWith("cm_")) {
      const token = await env.cybermeters_db
        .prepare(
          `SELECT t.id AS api_token_id, t.user_id,
                  t.workspace_id AS token_workspace_id,
                  t.scope        AS token_scope,
                  u.id, u.email, u.name, u.plan, u.status
           FROM api_tokens t
           JOIN users u ON u.id = t.user_id
           WHERE t.token_hash = ?
             AND t.status = 'active'
             AND (t.expires_at IS NULL OR t.expires_at > datetime('now'))
           LIMIT 1`
        )
        .bind(tokenHash)
        .first();
      if (!token || token.status === "suspended") return null;
      // Fire-and-forget: last_used_at + audit log (never block the request)
      env.cybermeters_db
        .prepare("UPDATE api_tokens SET last_used_at = datetime('now') WHERE id = ?")
        .bind(token.api_token_id)
        .run()
        .catch(() => {});
      createAuditEvent(env, {
        user_id:     token.user_id,
        event_type:  "api_token_used",
        entity_type: "api_token",
        entity_id:   token.api_token_id,
        description: "API token authenticated request",
        metadata:    { scope: token.token_scope, workspace_id: token.token_workspace_id ?? null },
      }).catch(() => {});
      return token;
    }

    // ── Session path ──────────────────────────────────────────────────────────
    const session = await env.cybermeters_db
      .prepare(
        `SELECT s.id AS session_id, s.user_id, u.id, u.email, u.name, u.plan, u.status
         FROM user_sessions s
         JOIN users u ON u.id = s.user_id
         WHERE s.token_hash = ? AND s.expires_at > datetime('now')`
      )
      .bind(tokenHash)
      .first();
    if (!session || session.status === "suspended") return null;
    // Fire-and-forget: track last activity time for session visibility feature
    env.cybermeters_db
      .prepare("UPDATE user_sessions SET last_seen_at = datetime('now') WHERE id = ?")
      .bind(session.session_id)
      .run()
      .catch(() => {});
    return session;
  } catch {
    return null;
  }
}

/**
 * @deprecated requireApiToken is now a thin shim.
 * requireAuth handles both cm_ API tokens and user sessions transparently.
 * All call sites should use requireAuth directly.
 */
async function requireApiToken(request, env) {
  return requireAuth(request, env);
}

/**
 * DNS-over-HTTPS query via Cloudflare (1.1.1.1).
 * Workers have no raw socket access; DoH is the Cloudflare-native approach.
 */
async function dnsQuery(name, type) {
  const res = await fetch(
    `https://cloudflare-dns.com/dns-query?name=${encodeURIComponent(name)}&type=${encodeURIComponent(type)}`,
    {
      headers: { Accept: "application/dns-json" },
      signal: AbortSignal.timeout(6_000),
    }
  );
  if (!res.ok) throw new Error(`DoH ${res.status} for ${type} ${name}`);
  return res.json();
}

async function dnsQueryDnssec(name, type) {
  const res = await fetch(
    `https://cloudflare-dns.com/dns-query?name=${encodeURIComponent(name)}&type=${encodeURIComponent(type)}&do=1`,
    {
      headers: { Accept: "application/dns-json" },
      signal: AbortSignal.timeout(6_000),
    }
  );
  if (!res.ok) throw new Error(`DoH DNSSEC ${res.status} for ${type} ${name}`);
  return res.json();
}

async function dnsQueryGoogle(name, type) {
  const res = await fetch(
    `https://dns.google/resolve?name=${encodeURIComponent(name)}&type=${encodeURIComponent(type)}`,
    { signal: AbortSignal.timeout(6_000) }
  );
  if (!res.ok) throw new Error(`Google DoH ${res.status} for ${type} ${name}`);
  return res.json();
}

async function dnsQueryQuad9(name, type) {
  // Quad9 DoH — optional third resolver for A/AAAA agreement checks.
  // Never throws: failure returns null so budget-safe.
  try {
    const res = await fetch(
      `https://dns.quad9.net/dns-query?name=${encodeURIComponent(name)}&type=${encodeURIComponent(type)}`,
      {
        headers: { Accept: "application/dns-json" },
        signal: AbortSignal.timeout(5_000),
      }
    );
    if (!res.ok) return null;
    return res.json();
  } catch {
    return null;
  }
}

function dnsAnswerValues(response) {
  return (response?.Answer || [])
    .map((r) => r.data)
    .filter(Boolean)
    .sort();
}

/**
 * computeResolverAgreementScore(resolvers)
 *
 * Given an array of { status, returned_records } resolver objects,
 * returns a 0–100 score:
 *   100 = all available resolvers agree
 *   50  = partial disagreement among available resolvers
 *   0   = all available resolvers disagree
 *   null = fewer than 2 resolvers available (insufficient data)
 */
function computeResolverAgreementScore(resolvers) {
  const available = resolvers.filter((r) => r.status === "ok");
  if (available.length < 2) return null;
  const reference = available[0].returned_records;
  const agreements = available.filter(
    (r) => r.returned_records.length === reference.length
      && r.returned_records.every((v, i) => v === reference[i])
  ).length;
  return Math.round((agreements / available.length) * 100);
}

function buildDnsCrossCheck(name, type, primaryResult, googleResult, quad9Result) {
  const primaryRecords = dnsAnswerValues(primaryResult);
  const googleAvailable = googleResult?.status === "fulfilled";
  const quad9Available  = quad9Result != null;
  const googleRecords   = googleAvailable ? dnsAnswerValues(googleResult.value) : [];
  const quad9Records    = quad9Available  ? dnsAnswerValues(quad9Result)         : [];

  const resolvers = [
    { resolver: "cloudflare", status: primaryResult ? "ok" : "unavailable", returned_records: primaryRecords },
    googleAvailable
      ? { resolver: "google",  status: "ok",          returned_records: googleRecords }
      : { resolver: "google",  status: "unavailable", returned_records: [] },
  ];
  if (quad9Result !== undefined) {
    resolvers.push(
      quad9Available
        ? { resolver: "quad9",  status: "ok",          returned_records: quad9Records }
        : { resolver: "quad9",  status: "unavailable", returned_records: [] }
    );
  }

  const agreementScore = computeResolverAgreementScore(resolvers.filter((r) => r.status === "ok").length >= 2 ? resolvers : resolvers.slice(0, 2));
  const googleRec = googleAvailable ? dnsAnswerValues(googleResult.value) : [];
  const sameRecords = googleAvailable
    && primaryRecords.length === googleRec.length
    && primaryRecords.every((v, i) => v === googleRec[i]);

  return {
    query: { name, type },
    primary_resolver: {
      resolver: "cloudflare",
      status: primaryResult ? "ok" : "unavailable",
      returned_records: primaryRecords,
    },
    cloudflare_resolver: {
      resolver: "cloudflare",
      status: primaryResult ? "ok" : "unavailable",
      returned_records: primaryRecords,
    },
    google_resolver: googleAvailable
      ? { resolver: "google", status: "ok", returned_records: googleRecords }
      : { resolver: "google", status: "unavailable", returned_records: [] },
    ...(quad9Result !== undefined ? {
      quad9_resolver: quad9Available
        ? { resolver: "quad9", status: "ok", returned_records: quad9Records }
        : { resolver: "quad9", status: "unavailable", returned_records: [] },
    } : {}),
    authoritative_nameserver: {
      status: "unavailable",
      reason: "Raw authoritative DNS queries are not available from Cloudflare Workers.",
      returned_records: [],
    },
    resolver_agreement_score: agreementScore,
    resolver_disagreement: googleAvailable ? !sameRecords : false,
  };
}

/**
 * HTTP fetch that never throws — returns null on timeout / network error.
 */
async function safeFetch(url, options = {}) {
  try {
    return await fetch(url, {
      ...options,
      signal: AbortSignal.timeout(10_000),
    });
  } catch {
    return null;
  }
}

