// ── Enterprise Benchmark Dataset ─────────────────────────────────────────────
//
// Known-good enterprise domains.  Used by:
//   • GET /api/validation/benchmark  — regression check
//   • computeScore                   — enterprise edge uncertainty detection
//
// Enterprise CDN deployments (Cloudflare Workers, Google Front End, Akamai, etc.)
// often serve different responses to automated scanner IPs than to real browsers.
// We track these domains so the scoring engine can apply conservative confidence
// when the probe results are internally contradictory.

const ENTERPRISE_BENCHMARK = [
  { domain: "google.com",     max_header_findings: 0, max_email_findings: 0, expect_https_redirect: true },
  { domain: "github.com",     max_header_findings: 0, max_email_findings: 0, expect_https_redirect: true },
  { domain: "cloudflare.com", max_header_findings: 0, max_email_findings: 0, expect_https_redirect: true },
  { domain: "microsoft.com",  max_header_findings: 0, max_email_findings: 0, expect_https_redirect: true },
  { domain: "amazon.com",     max_header_findings: 0, max_email_findings: 0, expect_https_redirect: true },
  { domain: "openai.com",     max_header_findings: 0, max_email_findings: 0, expect_https_redirect: true },
];

// Fast O(1) membership test used in computeScore
const ENTERPRISE_DOMAINS = new Set(ENTERPRISE_BENCHMARK.map(b => b.domain));

// Security posture category metadata — shared by computeSecurityPosture and
// the /scorecard/pdf-data route.  Defined at module scope so both can reference it.
const POSTURE_WEIGHTS = {
  email_security:   { label: 'Email Security',     pct: 20 },
  ssl_certificates: { label: 'SSL & Certificates', pct: 20 },
  attack_surface:   { label: 'Attack Surface',     pct: 25 },
  third_party_risk: { label: 'Third-Party Risk',   pct: 15 },
  admin_exposure:   { label: 'Admin Exposure',     pct: 20 },
};

// Sprint 9E.1: updated to support the Sprint 9C evidence array format.
// Sprint 9C changed finding.evidence from an object to an array of evidence items.
// Previously this function checked object fields directly on finding.evidence, which
// always produced "partial" quality after 9C because array fields (source, probe_target,
// etc.) are on the first array item, not on the array itself.
// Now normalizes to evidence[0] when evidence is an array; legacy object format still works.
function validateFindingEvidence(finding) {
  const warnings = [];
  const ev = finding?.evidence ?? null;

  // Normalize: Sprint 9C produces arrays; pre-9C scans may have legacy objects.
  const evidence = Array.isArray(ev) ? (ev[0] ?? null) : ev;

  if (!evidence) {
    warnings.push("missing evidence_json");
    return { evidence_quality: "missing", evidence_warnings: warnings };
  }

  if (!finding.confidence) warnings.push("missing confidence");

  // source: identical field name in both array-item and legacy object formats
  if (!evidence.source) warnings.push("missing source");

  // probe target: array-item format uses "label"; legacy uses probe_target/target/etc.
  if (!(evidence.label ?? evidence.probe_target ?? evidence.target ?? evidence.queried_hostname ?? evidence.requested_url)) {
    warnings.push("missing target or queried hostname");
  }

  // observed value: array-item format uses "value"; legacy uses observed_value/headers_observed/etc.
  const hasValue = evidence.value !== undefined
    || evidence.observed_value !== undefined
    || evidence.headers_observed
    || evidence.returned_records;
  if (!hasValue) warnings.push("missing observed value");

  // expected_value: same field name in both formats (preserved by Case B wrapping in Sprint 9C)
  if (finding.score_impact !== 0 && evidence.expected_value === undefined) {
    warnings.push("missing expected value");
  }

  // manual_verification_command and checked_at: same field names in both formats
  if (!evidence.manual_verification_command) warnings.push("missing manual verification command");
  if (!evidence.checked_at) warnings.push("missing checked_at timestamp");

  const evidence_quality = warnings.length === 0
    ? "excellent"
    : warnings.length <= 2
      ? "good"
      : "partial";

  return { evidence_quality, evidence_warnings: warnings };
}

function applyEvidenceQuality(findings) {
  return (findings || []).map((finding) => {
    const quality = validateFindingEvidence(finding);
    // Sprint 10A: propagate finding_type so it appears in computeScore output.
    // "finding" is set by the finding() helper; everything else defaults to "observation".
    return { ...finding, ...quality, finding_type: finding.finding_type ?? "observation" };
  });
}

// ── Sprint 9B: Confidence Engine ─────────────────────────────────────────────
//
// Converts legacy string confidence values and assigns deterministic numeric
// confidence scores (0–100) to all findings.
//
// Scale:
//   95  Verified observation     — direct probe, deterministic result
//   90  Multiple confirmations   — strong single source or corroborating signals
//   80  Strong evidence          — single validated probe, no ambiguity
//   70  Probable                 — heuristic with reasonable signal quality
//   60  Weak signal              — indirect inference or common-pattern heuristic
//   40  Unvalidated candidate    — generated algorithmically, no probe validation

/** Convert legacy string confidence values to numeric equivalents. */
const CONFIDENCE_STRING_TO_NUMERIC = {
  confirmed: 95,
  high:      90,
  medium:    70,
  low:       60,
};

/**
 * Per-finding-ID confidence scores (null-state assignments).
 * Applied when a finding has no existing confidence value.
 * Dynamic IDs (header_missing_*, subdomain_sensitive_*) are handled
 * by prefix patterns in resolveConfidence() below.
 */
const FINDING_CONFIDENCE_SCORES = {
  // ── DNS ──────────────────────────────────────────────────────────────────
  dns_no_resolution:               90, // fallback — string "high"→90 normally
  dns_resolver_disagreement:       70, // fallback — string "medium"→70 normally
  dnssec_not_enabled:              90, // fallback — string "high"→90 normally
  dnssec_misconfigured:            70, // fallback — string "medium"→70 normally
  // ── SSL ──────────────────────────────────────────────────────────────────
  ssl_not_available:               90, // TLS handshake confirmed failed
  ssl_no_http_redirect:            90, // confirmed variant; uncertain gets "low"→60
  canonical_url_uncertain:         70, // inferred from redirect chain
  // ── Email security ───────────────────────────────────────────────────────
  email_not_applicable:            90, // deterministic: no MX records
  email_missing_dmarc:             90, // direct DNS TXT lookup
  email_dmarc_policy_none:         90, // DMARC record parsed
  email_missing_spf:               90, // direct DNS TXT lookup
  email_dkim_not_detected:         60, // fallback default; finding sets 60/70/80 dynamically based on provider
  // ── Subdomains ───────────────────────────────────────────────────────────
  subdomains_large_attack_surface: 60, // CT inventory count is observed, reachability is not confirmed
  // ── Subdomain takeover ───────────────────────────────────────────────────
  subdomain_takeover:              90, // CNAME suffix + body fingerprint — dual signal
  // ── Asset exposure ───────────────────────────────────────────────────────
  asset_exposure_sensitive_tool:   90, // fallback — string "high"→90 normally
  asset_exposure_admin_interface:  70, // fallback — string "medium"→70 normally
  asset_exposure_dev_env:          70, // fallback — string "medium"→70 normally
  // ── WHOIS intelligence ───────────────────────────────────────────────────
  whois_domain_expired:            95, // RDAP expiry date is deterministic
  whois_expiry_critical:           95, // RDAP expiry date is deterministic
  whois_expiry_warning:            90, // deterministic date; 90d threshold is policy
  whois_new_domain:                90, // RDAP registration date is deterministic
  whois_registrar_info:            95, // RDAP entity data directly reported
  // ── Email security intelligence ──────────────────────────────────────────
  email_intel_dmarc_missing:        95, // same DNS probe as email_missing_dmarc
  email_intel_dmarc_reporting_only: 95, // DMARC record parsed
  email_intel_spf_missing:          95, // direct DNS TXT lookup
  email_intel_spf_permissive:       95, // SPF parsed — +all directly observed
  email_intel_dkim_not_found:       60, // common selector heuristic only
  email_intel_mta_sts_missing:      90, // HTTP probe to mta-sts. subdomain
  email_intel_tls_rpt_missing:      90, // DNS TXT at _smtp._tls.{domain}
  // ── Cloud storage discovery ──────────────────────────────────────────────
  cloud_storage_takeover_risk:      80, // fallback — string already set on most
  cloud_storage_public_listing:     90, // listing confirmed from HTTP body
  cloud_storage_exposure_observed:  80, // fallback — string already set on most
  // ── Admin surface detection ──────────────────────────────────────────────
  admin_surface_critical:  70, // fingerprint heuristic; authentication unverified
  admin_surface_high:      70, // fingerprint heuristic; authentication unverified
  admin_surface_medium:    60, // hostname pattern only; auth likely enforced
  // ── Domain security enrichment ───────────────────────────────────────────
  dse_missing_caa:               95, // direct DNS CAA lookup — deterministic
  dse_caa_no_issuers:            95, // CAA record parsed — no issue tags
  dse_hsts_short_maxage:         95, // HSTS header observed and parsed
  dse_hsts_not_preload_eligible: 90, // HSTS parsed; multiple eligibility criteria
  dse_cookie_no_secure:          90, // Set-Cookie header observed; one response
  dse_cookie_no_httponly:        90, // Set-Cookie header observed; one response
  dse_cookie_no_samesite:        90, // Set-Cookie header observed; one response
  // ── Technology detection ─────────────────────────────────────────────────
  tech_xpoweredby_version_disclosure: 90, // X-Powered-By header with version observed
  tech_server_version_disclosure:     90, // Server header with version observed
};

/**
 * resolveConfidence(finding) → number (0–100)
 *
 * Returns a deterministic numeric confidence score for any finding.
 * Priority order:
 *   1. Already numeric — return as-is (idempotent)
 *   2. Legacy string ("high", "medium", etc.) — convert to numeric
 *   3. Direct ID lookup in FINDING_CONFIDENCE_SCORES
 *   4. Prefix-based pattern match for dynamic finding IDs
 *   5. Default: 70
 */
function resolveConfidence(finding) {
  // 1. Already numeric — preserve
  if (typeof finding.confidence === "number") return finding.confidence;

  // 2. Legacy string confidence — convert
  if (typeof finding.confidence === "string") {
    const mapped = CONFIDENCE_STRING_TO_NUMERIC[finding.confidence.toLowerCase()];
    if (mapped != null) return mapped;
  }

  // 3. Direct ID lookup
  const id = finding.id ?? "";
  if (FINDING_CONFIDENCE_SCORES[id] != null) return FINDING_CONFIDENCE_SCORES[id];

  // 4. Prefix-based patterns for dynamic IDs
  if (id.startsWith("header_missing_"))       return 90; // direct HTTP header observation
  if (id.startsWith("header_malformed_"))     return 90; // direct HTTP header parse
  if (id.startsWith("subdomain_sensitive_"))  return 70; // keyword heuristic, unverified reachability
  if (id.startsWith("email_intel_"))          return 90; // DNS/HTTP verified
  if (id.startsWith("whois_"))               return 90; // RDAP verified
  if (id.startsWith("dse_"))                 return 90; // direct probe
  if (id.startsWith("tech_"))                return 90; // HTTP header observation
  if (id.startsWith("cloud_storage_"))       return 80; // probe-validated
  if (id.startsWith("admin_surface_"))       return 70; // fingerprint heuristic

  // 5. Default
  return 70;
}

/**
 * normalizeFindingSchema(finding)
 * Sprint 9A schema fields + Sprint 9B numeric confidence.
 *
 * Ensures every finding conforms to v2 schema with a numeric confidence score.
 * Spread-first — existing fields are preserved; only missing fields get defaults.
 */
// Sprint 9C: Build structured evidence array from any finding.
// Three cases:
//   A — evidence is already a non-empty array → return as-is
//   B — evidence is a non-null, non-array object (rich object) → normalize to array
//   C — evidence is null/undefined/[] → generate from finding fields (never invented)
function buildEvidenceArray(finding) {
  const ev = finding.evidence;

  // Case A: already a populated array — do not modify
  if (Array.isArray(ev) && ev.length > 0) return ev;

  // Case B: rich evidence object — normalize to array, preserving all fields
  if (ev != null && typeof ev === "object" && !Array.isArray(ev)) {
    const {
      evidence_type,
      probe_target,
      observed_value,
      expected_value,
      source,
      checked_at,
      manual_verification_command,
      ...rest
    } = ev;
    return [{
      type:                        evidence_type ?? "scan_probe",
      label:                       probe_target  ?? "Probe target",
      value:                       observed_value != null ? String(observed_value) : null,
      source:                      source ?? "CyberMeters",
      expected_value:              expected_value ?? null,
      checked_at:                  checked_at ?? null,
      manual_verification_command: manual_verification_command ?? null,
      ...rest,
    }];
  }

  // Case C: no evidence set — derive from finding fields
  return buildEvidenceFromFields(finding);
}

function buildEvidenceFromFields(finding) {
  const { id = "", module: mod = "", description = "" } = finding;

  // Subdomain sensitive — reconstruct subdomain from ID
  if (id.startsWith("subdomain_sensitive_")) {
    const sub = id.replace("subdomain_sensitive_", "").replace(/_/g, ".");
    return [{
      type:   "certificate_transparency",
      label:  "Subdomain discovered in CT logs",
      value:  sub,
      source: "certificate_transparency_log",
    }];
  }

  if (id === "subdomains_large_attack_surface") {
    return [{
      type:   "certificate_transparency",
      label:  "Subdomain count from CT logs",
      value:  description,
      source: "certificate_transparency_log",
    }];
  }

  if (id === "subdomain_takeover") {
    return [{
      type:   "dns_cname",
      label:  "Dangling CNAME detected",
      value:  description,
      source: "dns_lookup",
    }];
  }

  if (id === "asset_exposure_sensitive_tool" ||
      id === "asset_exposure_admin_interface" ||
      id === "asset_exposure_dev_env") {
    return [{
      type:   "http_probe",
      label:  "Reachable asset detected",
      value:  description,
      source: "cloudflare_workers_fetch",
    }];
  }

  if (id.startsWith("whois_")) {
    return [{
      type:   "rdap_lookup",
      label:  "RDAP registry query result",
      value:  description,
      source: "rdap",
    }];
  }

  if (id.startsWith("admin_surface_")) {
    return [{
      type:   "http_probe",
      label:  "Admin service fingerprint match",
      value:  description,
      source: "cloudflare_workers_fetch",
    }];
  }

  if (id === "dse_missing_caa" || id === "dse_caa_no_issuers") {
    return [{
      type:   "dns_lookup",
      label:  "DNS CAA record query",
      value:  description,
      source: "cloudflare_doh",
    }];
  }

  if (id.startsWith("dse_hsts_") || id.startsWith("dse_cookie_")) {
    return [{
      type:   "http_header_probe",
      label:  "HTTP response header observation",
      value:  description,
      source: "cloudflare_workers_fetch",
    }];
  }

  if (id.startsWith("tech_")) {
    return [{
      type:   "http_header_probe",
      label:  "Version disclosure in HTTP response header",
      value:  description,
      source: "cloudflare_workers_fetch",
    }];
  }

  if (id.startsWith("email_intel_")) {
    return [{
      type:   "dns_txt_lookup",
      label:  "DNS TXT record query",
      value:  description,
      source: "cloudflare_doh",
    }];
  }

  // Generic fallback — description always contains the observed condition
  return [{
    type:   "scanner_detection",
    label:  "Detection basis",
    value:  description,
    source: `CyberMeters/${mod}`,
  }];
}

function normalizeFindingSchema(finding) {
  return {
    ...finding,
    module:             finding.module             ?? null,
    confidence:         resolveConfidence(finding),         // Sprint 9B: always numeric
    validation_quality: finding.validation_quality ?? null,
    evidence:           buildEvidenceArray(finding),        // Sprint 9C: always array
    remediation_owner:  finding.remediation_owner  ?? null,
    finding_type:       finding.finding_type       ?? (finding.score_impact < 0 ? "finding" : "observation"),
  };
}

function isActionableFinding(finding) {
  return finding?.finding_type === "finding"
    || (finding?.finding_type == null && Number(finding?.score_impact) < 0);
}

