/**
 * detectVendorsFromModules — pure computation, zero network I/O.
 *
 * Reads signal strings already captured in `modules` during the scan phases
 * and matches them against VENDOR_SIGNATURES.
 *
 * Returns:
 *   { detected: bool, vendors: [{name, category, source, evidence, confidence, risk_level}],
 *     source: "module_correlation", error: null }
 *
 * `source`     — primary signal source that triggered the match (first evidence entry)
 * `confidence` — "high"   (≥3 independent sources matched)
 *                "medium" (2 sources matched)
 *                "low"    (1 source matched)
 */
function detectVendorsFromModules(modules) {
  try {
    // ── Collect signal strings from existing module data ───────────────────
    const signals = {
      spf:    [],
      mx:     [],
      ns:     [],
      dkim:   [],
      csp:    [],
      server: [],
      cname:  [],
      tech:   [],
    };

    // SPF record (covers include:/redirect:/exists: tokens)
    const spfRecord = (
      modules?.email_security?.spf?.record ||
      modules?.email_security_intelligence?.spf?.record || ""
    ).toLowerCase();
    if (spfRecord) signals.spf.push(spfRecord);

    // MX records
    for (const mx of (modules?.dns?.mx_records || [])) {
      if (mx?.value) signals.mx.push(mx.value.toLowerCase());
    }

    // Nameservers
    for (const ns of (modules?.dns?.nameservers || [])) {
      if (ns) signals.ns.push(ns.toLowerCase());
    }

    // DKIM selector
    const dkimSel = (
      modules?.email_security?.dkim?.selector ||
      modules?.email_security_intelligence?.dkim?.selector || ""
    ).toLowerCase();
    if (dkimSel) signals.dkim.push(dkimSel);

    // CSP header
    const csp = (modules?.headers?.values?.["content-security-policy"] || "").toLowerCase();
    if (csp) signals.csp.push(csp);

    // Server header (prefer technology_detection — more reliable than raw header)
    const srv = (
      modules?.technology_detection?.server ||
      modules?.headers?.values?.server || ""
    ).toLowerCase();
    if (srv) signals.server.push(srv);

    // CNAMEs from takeover risks
    for (const risk of (modules?.subdomain_takeover?.risks || [])) {
      if (risk?.cname) signals.cname.push(risk.cname.toLowerCase());
    }
    // CNAMEs from asset exposure probe
    for (const asset of (modules?.asset_exposure?.assets || [])) {
      if (asset?.cname) signals.cname.push(asset.cname.toLowerCase());
    }
    // CNAMEs from brute-force results
    for (const item of (modules?.dns_bruteforce?.items || [])) {
      if (item?.cname) signals.cname.push(item.cname.toLowerCase());
    }

    // Technology names (verbatim from technology_detection)
    for (const tech of (modules?.technology_detection?.technologies || [])) {
      if (tech) signals.tech.push(tech);
    }

    // ── Match signatures ──────────────────────────────────────────────────
    const vendors = [];

    for (const sig of VENDOR_SIGNATURES) {
      const evidence = [];

      for (const check of sig.signals) {
        const haystack = signals[check.source] || [];
        for (const val of haystack) {
          if (check.test(val)) {
            const detail = val.length > 120 ? val.slice(0, 120) + "…" : val;
            evidence.push({ source: check.source, detail });
            break;  // one hit per source type per vendor is enough
          }
        }
      }

      if (evidence.length === 0) continue;

      const confidence =
        evidence.length >= 3 ? "high" :
        evidence.length === 2 ? "medium" : "low";

      vendors.push({
        name:       sig.name,
        category:   sig.category,
        source:     evidence[0].source,   // primary signal source
        evidence,
        confidence,
        risk_level: sig.risk_level,
      });
    }

    return {
      detected: vendors.length > 0,
      vendors,
      source:   "module_correlation",
      error:    null,
    };
  } catch (err) {
    return {
      detected: false,
      vendors:  [],
      source:   "module_correlation",
      error:    err?.message ?? "Vendor detection failed",
    };
  }
}

const CERTIFICATE_AUTHORITY_VENDOR_PATTERNS = [
  { vendor_name: "Let's Encrypt",          owner: "ISRG",                  test: (v) => /\bisrg\b|\blet'?s encrypt\b/.test(v) },
  { vendor_name: "DigiCert",               owner: "DigiCert",              test: (v) => /\bdigicert\b|\bsymantec\b|\bgeotrust\b|\bthawte\b|\brapidssl\b/.test(v) },
  { vendor_name: "Sectigo",                test: (v) => /\bsectigo\b|\bcomodo\b|\busertrust\b/.test(v) },
  { vendor_name: "Cloudflare",             test: (v) => /\bcloudflare\b/.test(v) },
  { vendor_name: "Google Trust Services",  test: (v) => /\bgoogle trust services\b|\bgts\b/.test(v) },
  { vendor_name: "GlobalSign",             test: (v) => /\bglobalsign\b/.test(v) },
  { vendor_name: "Amazon Trust Services",  test: (v) => /\bamazon\b|\bamazon trust services\b/.test(v) },
  { vendor_name: "Microsoft",              test: (v) => /\bmicrosoft\b|\bazure tls\b/.test(v) },
  { vendor_name: "Entrust",                test: (v) => /\bentrust\b/.test(v) },
  { vendor_name: "GoDaddy",                test: (v) => /\bgodaddy\b|\bstarfield\b/.test(v) },
  { vendor_name: "ZeroSSL",                test: (v) => /\bzerossl\b/.test(v) },
];

function normalizeCertificateNamePart(value) {
  return typeof value === "string"
    ? value
        .normalize("NFKD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .replace(/[^\w\s'.-]/g, " ")
        .replace(/\s+/g, " ")
        .trim()
    : "";
}

function parseCertificateDistinguishedName(rawName) {
  const raw = typeof rawName === "string" ? rawName.trim() : "";
  const out = { common_name: null, organization: null, country: null };
  if (!raw) return out;

  const parts = raw.split(/\s*,\s*/);
  for (const part of parts) {
    const match = part.match(/^([A-Za-z]+)\s*=\s*(.+)$/);
    if (!match) continue;
    const key = match[1].toUpperCase();
    const value = match[2].trim();
    if (key === "CN") out.common_name = value;
    else if (key === "O") out.organization = value;
    else if (key === "C") out.country = value;
  }
  return out;
}

function normalizeCertificateIssuer(rawIssuer) {
  const raw = typeof rawIssuer === "string" ? rawIssuer.trim() : "";
  if (!raw || raw.toLowerCase() === "unknown") {
    return {
      raw: raw || null,
      normalized_name: "unknown",
      common_name: null,
      organization: null,
      country: null,
    };
  }

  const dn = parseCertificateDistinguishedName(raw);
  const display = dn.organization || dn.common_name || raw;
  return {
    raw,
    normalized_name: normalizeCertificateNamePart(display) || "unknown",
    common_name: dn.common_name,
    organization: dn.organization,
    country: dn.country,
  };
}

function mapCertificateAuthorityOwner(normalizedIssuer) {
  const normalizedName = typeof normalizedIssuer === "string"
    ? normalizeCertificateNamePart(normalizedIssuer)
    : normalizeCertificateNamePart([
        normalizedIssuer?.normalized_name,
        normalizedIssuer?.organization,
        normalizedIssuer?.common_name,
        normalizedIssuer?.raw,
      ].filter(Boolean).join(" "));

  if (!normalizedName || normalizedName === "unknown") {
    return {
      owner: "unknown",
      ca_family: "unknown",
      confidence: "unknown",
      source: "certificate_issuer",
    };
  }

  for (const pattern of CERTIFICATE_AUTHORITY_VENDOR_PATTERNS) {
    if (!pattern.test(normalizedName)) continue;
    return {
      owner: pattern.owner || pattern.vendor_name,
      ca_family: pattern.vendor_name,
      confidence: "high",
      source: "certificate_issuer",
    };
  }

  return {
    owner: "unknown",
    ca_family: "unknown",
    confidence: "unknown",
    source: "certificate_issuer",
  };
}

function unknownIfEmpty(value) {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value !== "string") return "unknown";
  const trimmed = value.trim();
  return trimmed ? trimmed : "unknown";
}

function extractCertificateCryptoMetadata(ssl) {
  const source = ssl || {};
  return {
    key_algorithm: unknownIfEmpty(source.cert_key_algorithm ?? source.key_algorithm ?? source.public_key_algorithm),
    key_size_bits: unknownIfEmpty(source.cert_key_size_bits ?? source.key_size_bits ?? source.public_key_size),
    signature_algorithm: unknownIfEmpty(source.cert_signature_algorithm ?? source.signature_algorithm),
  };
}

function detectSelfSignedCertificate(issuer, subject) {
  const issuerRaw = typeof issuer === "string" ? issuer.trim() : "";
  const subjectRaw = typeof subject === "string" ? subject.trim() : "";
  if (!issuerRaw || !subjectRaw) return "unknown";

  const issuerDn = parseCertificateDistinguishedName(issuerRaw);
  const subjectComparable = normalizeCertificateNamePart(subjectRaw);
  const issuerComparable = normalizeCertificateNamePart(issuerRaw);
  const issuerCnComparable = normalizeCertificateNamePart(issuerDn.common_name || "");

  if (
    issuerComparable &&
    subjectComparable &&
    (issuerComparable === subjectComparable || issuerCnComparable === subjectComparable)
  ) {
    return true;
  }

  return false;
}

function buildCertificateLifecycleIntelligence(certMod) {
  const rawDays = certMod?.days_until_expiry ?? certMod?.cert_expiry_days ?? null;
  const days = Number.isFinite(rawDays) ? Number(rawDays) : null;

  if (days === null) {
    return {
      days_to_expiry: null,
      expiry_band: "unknown",
      renewal_urgency: "unknown",
    };
  }

  let expiry_band = "healthy";
  let renewal_urgency = "normal";
  if (days < 0) {
    expiry_band = "expired";
    renewal_urgency = "urgent";
  } else if (days < 7) {
    expiry_band = "under_7_days";
    renewal_urgency = "urgent";
  } else if (days < 30) {
    expiry_band = "under_30_days";
    renewal_urgency = "soon";
  } else if (days < 90) {
    expiry_band = "under_90_days";
    renewal_urgency = "monitor";
  }

  return {
    days_to_expiry: days,
    expiry_band,
    renewal_urgency,
  };
}

function buildCaConcentrationAnalytics(observations, options = {}) {
  const source = options.source || "current_certificate_intelligence";
  const rows = Array.isArray(observations) ? observations : [];
  const normalizedRows = rows
    .map((entry) => {
      if (typeof entry === "string") {
        const issuer = entry.trim();
        return issuer ? { issuer, first_seen: null, last_seen: null } : null;
      }
      const issuer = String(entry?.issuer || "").trim();
      if (!issuer) return null;
      return {
        issuer,
        first_seen: entry?.first_seen || null,
        last_seen: entry?.last_seen || null,
      };
    })
    .filter(Boolean);
  const issuerList = normalizedRows.map((row) => row.issuer);
  const uniqueIssuers = [...new Set(issuerList)];

  if (uniqueIssuers.length === 0) {
    return {
      dependency: "unknown",
      issuers: [],
      issuer_count: 0,
      ca_owner_count: 0,
      dominant_ca_owner: "unknown",
      dominant_ca_share: 0,
      concentration_level: "unknown",
      first_observed: null,
      last_observed: null,
      source,
      observations: ["No certificate issuer was available from certificate intelligence."],
      recommendations: [],
    };
  }

  const ownerCounts = new Map();
  for (const issuer of issuerList) {
    const owner = mapCertificateAuthorityOwner(normalizeCertificateIssuer(issuer)).owner;
    const ownerKey = owner && owner !== "unknown" ? owner : "unknown";
    ownerCounts.set(ownerKey, (ownerCounts.get(ownerKey) || 0) + 1);
  }

  const sortedOwners = [...ownerCounts.entries()].sort((a, b) => b[1] - a[1]);
  const [dominantOwner, dominantCount] = sortedOwners[0] || ["unknown", 0];
  const dominantShare = issuerList.length > 0 ? Number((dominantCount / issuerList.length).toFixed(2)) : 0;
  const caOwnerCount = [...ownerCounts.keys()].filter((o) => o !== "unknown").length;
  const concentrationLevel =
    issuerList.length === 1 || dominantShare >= 0.8 ? "high" :
    dominantShare >= 0.5 ? "medium" : "low";

  const observationMessages = [
    uniqueIssuers.length === 1
      ? `Current certificate data shows a single observed issuer: ${uniqueIssuers[0]}.`
      : `Current certificate data shows ${uniqueIssuers.length} observed issuers.`,
  ];
  if (dominantOwner !== "unknown") {
    observationMessages.push(`${dominantOwner} is the dominant certificate authority owner in observed certificate data.`);
  }

  const firstObservedValues = normalizedRows.map((row) => row.first_seen).filter(Boolean).sort();
  const lastObservedValues = normalizedRows.map((row) => row.last_seen).filter(Boolean).sort();

  const recommendations = concentrationLevel === "high"
    ? ["Track CA dependency as an operational resilience risk and ensure renewal runbooks cover issuer outages or account issues."]
    : [];

  return {
    dependency: concentrationLevel === "high" ? "single_ca_dependency" : "multi_ca_dependency",
    issuers: uniqueIssuers,
    issuer_count: uniqueIssuers.length,
    ca_owner_count: caOwnerCount,
    dominant_ca_owner: dominantOwner,
    dominant_ca_share: dominantShare,
    concentration_level: concentrationLevel,
    first_observed: firstObservedValues[0] || null,
    last_observed: lastObservedValues[lastObservedValues.length - 1] || null,
    source,
    observations: observationMessages,
    recommendations,
  };
}

/**
 * normalizeCertificateAuthorityVendor(issuer)
 *
 * Maps certificate issuer strings to stable vendor inventory rows.
 * Returns null for unknown or empty issuers to avoid polluting vendor risk with
 * intermediate CA names that cannot be confidently mapped to an organisation.
 */
function normalizeCertificateAuthorityVendor(issuer) {
  const raw = typeof issuer === "string" ? issuer.trim() : "";
  if (!raw || raw.toLowerCase() === "unknown") return null;

  const normalizedIssuer = normalizeCertificateIssuer(raw);
  const normalized = normalizeCertificateNamePart([
    normalizedIssuer.normalized_name,
    normalizedIssuer.organization,
    normalizedIssuer.common_name,
    normalizedIssuer.raw,
  ].filter(Boolean).join(" "));

  for (const pattern of CERTIFICATE_AUTHORITY_VENDOR_PATTERNS) {
    if (!pattern.test(normalized)) continue;
    return {
      vendor_name: pattern.vendor_name,
      vendor_type: "certificate_authority",
      confidence: "high",
      source: "certificate_issuer",
    };
  }

  return null;
}

// ── Third-Party Asset Discovery ───────────────────────────────────────────────
// Derives a focused, business-facing view of external SaaS dependencies from the
// already-computed vendor_risk module.  Excludes infrastructure/CDN/cloud/hosting
// vendors (those are not "third-party SaaS" in the customer-facing sense) and
// remaps the remaining vendors to a business-readable category taxonomy:
//
//   email         → Microsoft 365, Google Workspace, Zoho, GoDaddy Email, Proton,
//                   Proofpoint, Mimecast, Barracuda
//   crm           → HubSpot, Salesforce, Marketo
//   support       → Zendesk, Intercom, Freshdesk
//   collaboration → Atlassian
//   marketing     → Mailchimp, SendGrid, Klaviyo, Mailgun, Brevo
//   ecommerce     → Shopify, Squarespace, Webflow
//
// Zero network I/O — wraps detectVendorsFromModules.

/** Maps (vendorName, existingCategory) → third-party category, or null to exclude. */
function remapToThirdPartyCategory(vendorName, existingCategory) {
  // Skip infrastructure-layer vendors — not third-party SaaS
  if (
    existingCategory === "infrastructure" ||
    existingCategory === "cloud"          ||
    existingCategory === "hosting"
  ) return null;

  if (existingCategory === "email_identity") return "email";
  if (existingCategory === "support")        return "support";
  if (existingCategory === "ecommerce")      return "ecommerce";

  // saas category: per-vendor CRM / collaboration / marketing split
  if (existingCategory === "saas") {
    const lookup = {
      "HubSpot":    "crm",
      "Salesforce": "crm",
      "Marketo":    "crm",
      "Atlassian":  "collaboration",
      "SendGrid":   "marketing",
      "Mailchimp":  "marketing",
      "Mailgun":    "marketing",
      "Brevo":      "marketing",
      "Klaviyo":    "marketing",
      // Payment processors — present in vendor_risk but not surfaced as
      // "third-party assets" for the business discovery view.
      "Stripe":     null,
      "PayPal":     null,
    };
    return Object.prototype.hasOwnProperty.call(lookup, vendorName)
      ? lookup[vendorName]
      : null;
  }

  return null;
}

/**
 * runThirdPartyDiscoveryModule — pure computation, zero network I/O.
 *
 * Builds a business-readable third-party SaaS inventory from signals already
 * captured in other modules.  Reuses detectVendorsFromModules internally.
 *
 * Returns:
 *   { detected: bool, total: number,
 *     assets: [{name, category, source, evidence, confidence, risk_level}],
 *     source: "third_party_discovery", error: null }
 */
function runThirdPartyDiscoveryModule(modules) {
  try {
    const vendorResult = detectVendorsFromModules(modules);
    const assets = [];

    for (const v of vendorResult.vendors) {
      const tpCategory = remapToThirdPartyCategory(v.name, v.category);
      if (!tpCategory) continue;

      assets.push({
        name:       v.name,
        category:   tpCategory,
        source:     v.source,
        evidence:   v.evidence,
        confidence: v.confidence,
        risk_level: v.risk_level,
      });
    }

    // Sort: email → crm → collaboration → support → marketing → ecommerce
    const catOrder = { email: 0, crm: 1, collaboration: 2, support: 3, marketing: 4, ecommerce: 5 };
    assets.sort((a, b) => (catOrder[a.category] ?? 9) - (catOrder[b.category] ?? 9));

    return {
      detected: assets.length > 0,
      total:    assets.length,
      assets,
      source:   "third_party_discovery",
      error:    null,
    };
  } catch (err) {
    return {
      detected: false,
      total:    0,
      assets:   [],
      source:   "third_party_discovery",
      error:    err?.message ?? "Third-party discovery failed",
    };
  }
}

// ── SaaS Exposure Discovery ───────────────────────────────────────────────────
