/**
 * runVendorRelationshipModule(modules)
 * Phase 7k — pure computation, zero network I/O.
 *
 * Parses CSP header per-directive, extracts hostnames from script-src,
 * connect-src, frame-src, img-src, and font-src; also uses CNAME signals
 * for high-confidence DNS-level matches.
 *
 * Confidence:
 *   high   — CNAME match or ≥2 independent CSP directives
 *   medium — single specific CSP directive match
 *   low    — csp:any (full-string fallback) only
 */
function runVendorRelationshipModule(modules) {
  try {
    // ── Build signal sets ────────────────────────────────────────────────────
    const rawCsp = (modules?.headers?.values?.["content-security-policy"] || "").toLowerCase();
    const directives = parseCspDirectives(rawCsp);

    // Script hosts from the first HTML body chunk read by runTechModule.
    const scriptHosts = Array.isArray(modules?.technology_detection?.external_scripts)
      ? modules.technology_detection.external_scripts.map((h) => String(h).toLowerCase())
      : [];

    // CNAME targets for DNS-level high-confidence signals
    const cnames = [];
    for (const risk of (modules?.subdomain_takeover?.risks || [])) {
      if (risk?.cname) cnames.push(risk.cname.toLowerCase());
    }
    for (const asset of (modules?.asset_exposure?.assets || [])) {
      if (asset?.cname) cnames.push(asset.cname.toLowerCase());
    }
    for (const item of (modules?.dns_bruteforce?.items || [])) {
      if (item?.cname) cnames.push(item.cname.toLowerCase());
    }

    // ── Signal tester ────────────────────────────────────────────────────────
    function testSignal(signal) {
      if (signal.source.startsWith("csp:")) {
        const directive = signal.source.slice(4);
        if (directive === "any") {
          for (const hosts of Object.values(directives)) {
            if (hosts.some(h => signal.test(h))) return true;
          }
          return false;
        }
        const hosts = directives[directive] || [];
        return hosts.some(h => signal.test(h));
      }
      if (signal.source === "cname") {
        return cnames.some(h => signal.test(h));
      }
      if (signal.source === "script") {
        return scriptHosts.some(h => signal.test(h));
      }
      return false;
    }

    // ── Match signatures ─────────────────────────────────────────────────────
    const vendors = [];

    for (const sig of VENDOR_RELATIONSHIP_SIGS) {
      const matchedSources = [];
      for (const check of sig.signals) {
        if (testSignal(check)) matchedSources.push(check.source);
      }
      if (matchedSources.length === 0) continue;

      // Confidence rules
      const hasCname       = matchedSources.includes("cname");
      const hasScript      = matchedSources.includes("script");
      const specificDirs   = matchedSources.filter(s => s.startsWith("csp:") && s !== "csp:any");
      const hasAnyOnly     = matchedSources.every(s => s === "csp:any");

      let confidence;
      if (hasCname || specificDirs.length >= 2) confidence = "high";
      else if (hasScript || specificDirs.length === 1) confidence = "medium";
      else                                        confidence = "low";

      vendors.push({
        name:           sig.name,
        category:       sig.category,
        risk_level:     sig.risk_level,
        confidence,
        source:         matchedSources[0],
        source_signals: matchedSources,
      });
    }

    const byCategory = {};
    for (const v of vendors) {
      byCategory[v.category] = (byCategory[v.category] || 0) + 1;
    }

    const highConfidenceCount = vendors.filter(v => v.confidence === "high").length;

    return {
      detected:        vendors.length > 0,
      vendors,
      total:           vendors.length,
      high_confidence: highConfidenceCount,
      by_category:     byCategory,
      source:          "csp_relationship_analysis",
      error:           null,
    };
  } catch (err) {
    return {
      detected:        false,
      vendors:         [],
      total:           0,
      high_confidence: 0,
      by_category:     {},
      source:          "csp_relationship_analysis",
      error:           err?.message ?? "Vendor relationship analysis failed",
    };
  }
}

/**
 * upsertVendorRelationships(domainId, relModule, env)
 * Phase 8g: Persists vendor_relationship detections into workspace_vendors
 * with source_module = 'vendor_relationship'.
 *
 * Uses INSERT OR IGNORE + UPDATE to preserve first_seen and refresh last_seen.
 * Does NOT mark undetected vendors inactive — vendor_risk (Phase 8c) handles
 * that sweep for DNS-sourced entries.
 */
async function upsertVendorRelationships(domainId, relModule, env) {
  if (!relModule?.detected || !relModule.vendors?.length) return;

  let wsRows;
  try {
    const r = await env.cybermeters_db
      .prepare("SELECT workspace_id FROM workspace_domains WHERE domain_id = ?")
      .bind(domainId)
      .all();
    wsRows = r.results || [];
  } catch { return; }
  if (wsRows.length === 0) return;

  const now = new Date().toISOString();

  for (const { workspace_id } of wsRows) {
    for (const v of relModule.vendors) {
      try {
        const id           = createId("vendor");
        const evidenceJson = JSON.stringify(v.source_signals || []);

        await env.cybermeters_db
          .prepare(
            `INSERT OR IGNORE INTO workspace_vendors
               (id, workspace_id, vendor_name, category, source, evidence,
                confidence, risk_level, source_module,
                first_seen, last_seen, status, created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'vendor_relationship', ?, ?, 'active', ?, ?)`
          )
          .bind(
            id, workspace_id, v.name, v.category, v.source, evidenceJson,
            v.confidence, v.risk_level, now, now, now, now
          )
          .run();

        await env.cybermeters_db
          .prepare(
            `UPDATE workspace_vendors
             SET last_seen = ?, confidence = ?, risk_level = ?,
                 evidence = ?, source_module = 'vendor_relationship',
                 status = 'active', updated_at = ?
             WHERE workspace_id = ? AND vendor_name = ? AND category = ?`
          )
          .bind(now, v.confidence, v.risk_level, evidenceJson, now, workspace_id, v.name, v.category)
          .run();
      } catch { /* non-fatal per-vendor */ }
    }
  }
}

// ── Vendor Risk Engine v1 Scoring ────────────────────────────────────────────

const VENDOR_CATEGORY_MULTIPLIERS = {
  identity_provider: 3.0,
  payment_processor: 2.5,
  dns_provider: 2.0,
  cdn: 2.0,
  email_provider: 1.5,
  analytics: 1.2,
  marketing: 1.2,
  hosting: 1.0,
  monitoring: 1.0,
  security_tooling: 1.0,
  other: 1.0,
};

const VENDOR_CONCENTRATION_WEIGHTS = {
  identity_provider: 5,
  payment_processor: 5,
  dns_provider: 4,
  cdn: 4,
  email_provider: 3,
  analytics: 1,
  marketing: 1,
  hosting: 1,
  monitoring: 1,
  security_tooling: 1,
  other: 1,
};

const VENDOR_SIGNAL_WEIGHTS = {
  "csp:script-src": 1.0,
  "csp:connect-src": 0.95,
  script: 0.85,
  cname: 0.9,
  headers: 0.6,
  header: 0.6,
  server: 0.6,
  tech: 0.6,
};

function confidenceToScore(confidence) {
  if (typeof confidence === "number") return Math.max(0, Math.min(1, confidence));
  const c = String(confidence || "").toLowerCase();
  if (c === "high") return 1.0;
  if (c === "medium") return 0.6;
  if (c === "low") return 0.25;
  return 0.1;
}

function normalizeVendorKey(vendorName) {
  const raw = String(vendorName || "").toLowerCase().trim();
  if (!raw) return "unknown";
  const normalized = raw
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "")
    .replace(/[^\w.\s-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (/stripe|js\.stripe\.com|assets\.stripe\.com/.test(normalized)) return "stripe";
  if (/cloudflare|cdnjs/.test(normalized)) return "cloudflare";
  if (/google|gtm|googletagmanager|google analytics|gts|recaptcha/.test(normalized)) return "google";
  if (/intercom|intercomcdn/.test(normalized)) return "intercom";
  if (/hotjar/.test(normalized)) return "hotjar";
  if (/segment/.test(normalized)) return "segment";
  if (/amplitude/.test(normalized)) return "amplitude";
  if (/paypal|paypalobjects/.test(normalized)) return "paypal";
  if (/microsoft|entra|office|outlook|azure/.test(normalized)) return "microsoft";
  if (/amazon|aws|cloudfront/.test(normalized)) return "aws";
  if (/zendesk|zdassets/.test(normalized)) return "zendesk";
  if (/hubspot|hubapi|hs-scripts|hsforms/.test(normalized)) return "hubspot";
  if (/salesforce|force\.com/.test(normalized)) return "salesforce";
  if (/okta/.test(normalized)) return "okta";
  if (/auth0/.test(normalized)) return "auth0";
  if (/datadog/.test(normalized)) return "datadog";

  return normalized
    .replace(/\.(com|net|org|io|co|app|dev|cloud|me)$/g, "")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "") || "unknown";
}

function getVendorSources(row) {
  const sources = new Set();
  if (row?.source) sources.add(String(row.source));
  for (const s of (Array.isArray(row?._sources) ? row._sources : [])) sources.add(String(s));
  try {
    const parsed = typeof row?.evidence === "string" ? JSON.parse(row.evidence || "[]") : row?.evidence;
    for (const item of (Array.isArray(parsed) ? parsed : [])) {
      if (typeof item === "string") sources.add(item);
      else if (item?.source) sources.add(String(item.source));
    }
  } catch { /* ignore malformed evidence */ }
  return [...sources].filter(Boolean);
}

function signalWeightForSource(source) {
  const s = String(source || "").toLowerCase();
  if (VENDOR_SIGNAL_WEIGHTS[s] !== undefined) return VENDOR_SIGNAL_WEIGHTS[s];
  if (s.startsWith("csp:script-src")) return 1.0;
  if (s.startsWith("csp:connect-src")) return 0.95;
  if (s.startsWith("csp:")) return 0.9;
  if (["ns", "mx", "spf", "dkim"].includes(s)) return 0.9;
  if (["server", "tech", "x-powered-by", "via", "x-cache"].includes(s)) return 0.6;
  return 0.75;
}

function signalWeightForVendor(row) {
  const sources = getVendorSources(row);
  if (sources.length === 0) return 0.75;
  return Math.max(...sources.map(signalWeightForSource));
}

function normalizeVendorRiskCategory(category, vendorName = "", source = "") {
  const c = String(category || "").toLowerCase();
  const name = String(vendorName || "").toLowerCase();
  const src = String(source || "").toLowerCase();

  if (c === "identity_provider" || c === "identity") return "identity_provider";
  if (c === "payment_processor" || c === "payments") return "payment_processor";
  if (c === "dns_provider") return "dns_provider";
  if (c === "email_provider" || c === "email_identity") return "email_provider";
  if (c === "analytics") return "analytics";
  if (c === "marketing") return "marketing";
  if (c === "monitoring") return "monitoring";
  if (c === "security_tooling" || c === "security" || c === "certificate_authority") return "security_tooling";
  if (c === "cdn") return "cdn";
  if (c === "hosting" || c === "cloud") return "hosting";

  if (c === "infrastructure") {
    if (/cloudflare|akamai|fastly/.test(name)) return src === "ns" ? "dns_provider" : "cdn";
    return "cdn";
  }

  if (c === "saas") {
    if (/stripe|paypal|braintree|square|adyen|klarna|paddle/.test(name)) return "payment_processor";
    if (/sendgrid|mailchimp|mailgun|brevo|klaviyo|marketo|hubspot/.test(name)) return "marketing";
    return "other";
  }

  if (c === "support" || c === "collaboration" || c === "crm" || c === "ecommerce") return "other";
  return "other";
}

function riskLevelBaseScore(riskLevel) {
  const r = String(riskLevel || "").toLowerCase();
  if (r === "high" || r === "critical") return 80;
  if (r === "medium") return 60;
  if (r === "low") return 40;
  return 30;
}

function scoreVendorRisk(row, categoryCounts, totalVendors) {
  const normalizedCategory = normalizeVendorRiskCategory(row.category, row.vendor_name, row.source);
  const multiplier = VENDOR_CATEGORY_MULTIPLIERS[normalizedCategory] ?? 1.0;
  const signalWeight = signalWeightForVendor(row);
  const confidenceScore = Number((confidenceToScore(row.confidence) * signalWeight).toFixed(3));
  const base = Math.round(riskLevelBaseScore(row.risk_level) * confidenceScore);
  const categoryCount = categoryCounts[normalizedCategory] || 0;
  const concentrationRatio = totalVendors > 0 ? categoryCount / totalVendors : 0;
  const concentrationPenalty = concentrationRatio >= 0.5 && categoryCount >= 3
    ? 15
    : concentrationRatio >= 0.35 && categoryCount >= 2
      ? 8
      : 0;
  const score = Math.max(0, Math.min(100, Math.round(base * multiplier - concentrationPenalty)));
  return {
    normalized_category: normalizedCategory,
    score,
    category_multiplier: multiplier,
    concentration_penalty: concentrationPenalty,
    confidence_score: confidenceScore,
    signal_weight: signalWeight,
  };
}

function classifyWorkspaceVendorConcentration(vendors) {
  if (vendors.length === 0) {
    return { level: "low", dominant_category: null, dominant_count: 0, dominant_ratio: 0, weighted_dominance: 0, total_weight: 0 };
  }
  const weights = {};
  let totalWeight = 0;
  for (const v of vendors) {
    const cat = v.normalized_category || normalizeVendorRiskCategory(v.category, v.vendor_name, v.source);
    const weight = VENDOR_CONCENTRATION_WEIGHTS[cat] ?? 1;
    weights[cat] = (weights[cat] || 0) + weight;
    totalWeight += weight;
  }
  const [dominant_category, weighted_dominance] = Object.entries(weights)
    .sort((a, b) => b[1] - a[1])[0];
  const dominant_ratio = totalWeight > 0 ? weighted_dominance / totalWeight : 0;
  const level =
    dominant_ratio >= 0.65 ? "high" :
    dominant_ratio >= 0.45 ? "medium" : "low";
  return {
    level,
    dominant_category,
    dominant_count: vendors.filter((v) => (v.normalized_category || normalizeVendorRiskCategory(v.category, v.vendor_name, v.source)) === dominant_category).length,
    dominant_ratio: Number(dominant_ratio.toFixed(2)),
    weighted_dominance,
    total_weight: totalWeight,
  };
}

function computeWorkspaceVendorRisk(vendors) {
  const active = vendors.filter((v) => (v.status || "active") === "active");
  if (active.length === 0) {
    return {
      workspace_vendor_risk_score: 0,
      concentration_risk: classifyWorkspaceVendorConcentration([]),
      top_vendors: [],
      scored_vendors: [],
    };
  }

  const canonical = new Map();
  for (const row of active) {
    const vendor_key = normalizeVendorKey(row.vendor_name || row.name);
    const normalized_category = normalizeVendorRiskCategory(row.category, row.vendor_name || row.name, row.source);
    const existing = canonical.get(vendor_key);
    const candidate = {
      ...row,
      vendor_key,
      normalized_category,
      _sources: getVendorSources(row),
    };
    if (!existing) {
      canonical.set(vendor_key, candidate);
      continue;
    }

    const existingSignal = signalWeightForVendor(existing);
    const candidateSignal = signalWeightForVendor(candidate);
    const existingRank = riskLevelBaseScore(existing.risk_level) * confidenceToScore(existing.confidence) * existingSignal;
    const candidateRank = riskLevelBaseScore(candidate.risk_level) * confidenceToScore(candidate.confidence) * candidateSignal;
    const kept = candidateRank > existingRank ? candidate : existing;
    kept._sources = [...new Set([...(existing._sources || []), ...(candidate._sources || [])])];
    canonical.set(vendor_key, kept);
  }

  const deduped = [...canonical.values()];
  const categoryCounts = {};
  for (const row of deduped) {
    const cat = row.normalized_category || normalizeVendorRiskCategory(row.category, row.vendor_name, row.source);
    categoryCounts[cat] = (categoryCounts[cat] || 0) + 1;
  }

  const scored = deduped.map((row) => ({
    ...row,
    ...scoreVendorRisk(row, categoryCounts, deduped.length),
  }));
  const concentration = classifyWorkspaceVendorConcentration(scored);
  const topVendors = scored.slice().sort((a, b) => b.score - a.score).slice(0, 10);
  const topAvg = topVendors.length
    ? topVendors.reduce((sum, v) => sum + v.score, 0) / topVendors.length
    : 0;
  const concentrationBump = concentration.level === "high" ? 10 : concentration.level === "medium" ? 5 : 0;

  return {
    workspace_vendor_risk_score: Math.max(0, Math.min(100, Math.round(topAvg + concentrationBump))),
    concentration_risk: concentration,
    top_vendors: topVendors,
    scored_vendors: scored,
  };
}

async function recomputeWorkspaceVendorRiskScores(workspaceId, env) {
  if (!workspaceId) return null;
  const now = new Date().toISOString();
  const rows = await env.cybermeters_db
    .prepare(
      `SELECT id, workspace_id, vendor_name, category, source, evidence,
              confidence, risk_level, status, first_seen, last_seen,
              metadata_json
       FROM workspace_vendors
       WHERE workspace_id = ? AND status = 'active'`
    )
    .bind(workspaceId)
    .all();

  const vendors = rows.results || [];
  const aggregate = computeWorkspaceVendorRisk(vendors);
  const scoredIds = aggregate.scored_vendors.map((v) => v.id).filter(Boolean);

  try {
    if (scoredIds.length > 0) {
      const placeholders = scoredIds.map(() => "?").join(", ");
      await env.cybermeters_db
        .prepare(
          `DELETE FROM vendor_risk_scores
           WHERE workspace_id = ? AND vendor_id NOT IN (${placeholders})`
        )
        .bind(workspaceId, ...scoredIds)
        .run();
    } else {
      await env.cybermeters_db
        .prepare("DELETE FROM vendor_risk_scores WHERE workspace_id = ?")
        .bind(workspaceId)
        .run();
    }
  } catch { /* score cleanup is non-fatal */ }

  for (const v of aggregate.scored_vendors) {
    try {
      await env.cybermeters_db
        .prepare(
          `INSERT OR REPLACE INTO vendor_risk_scores
             (vendor_id, workspace_id, score, category_multiplier,
              concentration_penalty, updated_at)
           VALUES (?, ?, ?, ?, ?, ?)`
        )
        .bind(
          v.id, workspaceId, v.score, v.category_multiplier,
          v.concentration_penalty, now
        )
        .run();
      await env.cybermeters_db
        .prepare(
          `INSERT INTO vendor_risk_scores_history
             (id, vendor_id, workspace_id, score, snapshot_time)
           VALUES (?, ?, ?, ?, ?)`
        )
        .bind(createId("vscorehist"), v.id, workspaceId, v.score, now)
        .run();
    } catch { /* score persistence is non-fatal per vendor */ }
  }

  return aggregate;
}

async function recomputeVendorRiskScoresForDomain(domainId, env) {
  let wsRows;
  try {
    const r = await env.cybermeters_db
      .prepare("SELECT workspace_id FROM workspace_domains WHERE domain_id = ?")
      .bind(domainId)
      .all();
    wsRows = r.results || [];
  } catch { return; }

  for (const { workspace_id } of wsRows) {
    try {
      await recomputeWorkspaceVendorRiskScores(workspace_id, env);
    } catch { /* migration may not be applied yet; scans must not fail */ }
  }
}

// ── Executive Security Scorecard ─────────────────────────────────────────────
//
// Aggregates data from D1 (structured tables) + R2 (latest scan report modules)
// into a business-friendly security scorecard.  Shared by:
//   GET /api/workspaces/:id/scorecard
//   GET /api/workspaces/:id/scorecard/report

// ── Security Posture Scoring ──────────────────────────────────────────────────
//
// Computes five category scores (0-100) from existing scorecard + R2 report data.
// No new queries — pure function over already-loaded data.
//
// Weights (must sum to 1.0):
//   Email Security:    20%
//   SSL & Certs:       20%
//   Attack Surface:    25%
//   Third-Party Risk:  15%
//   Admin Exposure:    20%

function scoreStatus(s) {
  if (s === null)  return 'unknown';
  if (s >= 90)     return 'good';
  if (s >= 70)     return 'fair';
  if (s >= 50)     return 'warning';
  return 'critical';
}

function clamp(n, lo = 0, hi = 100) { return Math.max(lo, Math.min(hi, n)); }

/**
 * computeSecurityPosture(sc, report)
 *
 * @param {object} sc     — the scorecard object (all D1-derived fields)
 * @param {object|null} report — the R2 JSON report (may be null if no scan yet)
 * @returns {{ email_security, ssl_certificates, attack_surface,
 *             third_party_risk, admin_exposure, overall_score }}
 */
function computeSecurityPosture(sc, report) {
  const em   = report?.modules?.email_security   ?? null;
  const ssl  = report?.modules?.ssl              ?? null;
  const adm  = report?.modules?.admin_surface_detection ?? null;

  // ── 1. Email Security ────────────────────────────────────────────────────────
  let emailScore   = 100;
  const emailReasons = [];

  if (em === null) {
    emailScore = null;
  } else {
    if (!em.spf?.present) {
      emailScore -= 25;
      emailReasons.push('Missing SPF record — any server can send mail as this domain');
    }
    if (!em.dmarc?.present) {
      emailScore -= 30;
      emailReasons.push('Missing DMARC policy — email spoofing is not prevented');
    } else if (em.dmarc.policy === 'none') {
      emailScore -= 10;
      emailReasons.push('DMARC policy is p=none (monitor-only) — spoofed mail is not rejected');
    }
    if (!em.dkim?.present) {
      emailReasons.push('DKIM could not be verified using common selectors; a custom selector may be in use');
    }
    emailScore = clamp(emailScore);
  }

  // ── 2. SSL & Certificates ────────────────────────────────────────────────────
  let sslScore   = 100;
  const sslReasons = [];

  if (ssl === null && sc.certificate_risks.risk_level === null) {
    sslScore = null;
  } else {
    if (ssl !== null) {
      if (!ssl.https_available) {
        sslScore -= 40;
        sslReasons.push('HTTPS is not available — all traffic is unencrypted');
      }
      // Only deduct for missing redirect when the chain was confirmed observable
      // and there is no enterprise edge contradiction (same guard as scoring engine)
      const redirectValidated = ssl.http_redirect_chain?.http_redirect_validated !== false;
      const enterpriseContradiction = ENTERPRISE_DOMAINS.has(sc.last_scanned_domain ?? '')
        && redirectValidated
        && !ssl.http_redirects_to_https
        && (report?.modules?.headers?.final_https !== false);
      if (!ssl.http_redirects_to_https && redirectValidated && !enterpriseContradiction) {
        sslScore -= 15;
        sslReasons.push('HTTP does not redirect to HTTPS — unencrypted access is possible');
      }
    }
    // Certificate expiry
    const daysLeft = sc.certificate_risks.days_until_expiry;
    if (daysLeft !== null) {
      if (daysLeft < 0) {
        sslScore -= 35;
        sslReasons.push('Certificate has expired');
      } else if (daysLeft < 7) {
        sslScore -= 25;
        sslReasons.push(`Certificate expires in ${daysLeft} day${daysLeft !== 1 ? 's' : ''} — renewal is critical`);
      } else if (daysLeft < 30) {
        sslScore -= 15;
        sslReasons.push(`Certificate expires in ${daysLeft} days — renew soon`);
      }
    }
    // Certificate intelligence signals
    const certRisk = sc.certificate_risks.risk_level;
    if (certRisk === 'critical') {
      sslScore -= 20;
      sslReasons.push('Certificate intelligence: critical-risk signal detected');
    } else if (certRisk === 'high') {
      sslScore -= 10;
      sslReasons.push('Certificate intelligence: high-risk signal detected');
    }
    sslScore = clamp(sslScore);
  }

  // ── 3. Attack Surface ────────────────────────────────────────────────────────
  let asScore   = 100;
  const asReasons = [];

  const brandHigh = sc.brand_risks.high   ?? 0;
  const brandMed  = sc.brand_risks.medium ?? 0;
  const newA30    = sc.new_assets_30d     ?? 0;
  const cloudN    = Array.isArray(report?.modules?.cloud_storage_discovery?.assets)
    ? report.modules.cloud_storage_discovery.assets.length : 0;

  if (brandHigh > 0) {
    const cut = clamp(brandHigh * 12, 0, 35);
    asScore -= cut;
    asReasons.push(`${brandHigh} high-risk brand impersonation domain${brandHigh !== 1 ? 's' : ''} actively resolving`);
  }
  if (brandMed > 0) {
    const cut = clamp(brandMed * 5, 0, 15);
    asScore -= cut;
    asReasons.push(`${brandMed} medium-risk typosquat domain${brandMed !== 1 ? 's' : ''} detected`);
  }
  if (newA30 > 0) {
    const cut = clamp(newA30 * 4, 0, 20);
    asScore -= cut;
    asReasons.push(`${newA30} new asset${newA30 !== 1 ? 's' : ''} discovered in the last 30 days — surface is expanding`);
  }
  if (cloudN > 0) {
    asScore -= 10;
    asReasons.push(`${cloudN} cloud storage asset${cloudN !== 1 ? 's' : ''} exposed`);
  }
  asScore = clamp(asScore);

  // ── 4. Third-Party Risk ──────────────────────────────────────────────────────
  let tpScore   = 100;
  const tpReasons = [];

  const vHigh = sc.vendor_risk.high   ?? 0;
  const vMed  = sc.vendor_risk.medium ?? 0;
  const tpa   = sc.third_party_assets ?? 0;
  const saas  = sc.saas_exposures     ?? 0;

  if (vHigh > 0) {
    const cut = clamp(vHigh * 15, 0, 40);
    tpScore -= cut;
    tpReasons.push(`${vHigh} high-risk vendor${vHigh !== 1 ? 's' : ''} in the supply chain`);
  }
  if (vMed > 0) {
    const cut = clamp(vMed * 5, 0, 20);
    tpScore -= cut;
    tpReasons.push(`${vMed} medium-risk vendor${vMed !== 1 ? 's' : ''} detected`);
  }
  if (tpa > 0) {
    const cut = clamp(tpa * 3, 0, 15);
    tpScore -= cut;
    tpReasons.push(`${tpa} third-party service${tpa !== 1 ? 's' : ''} with external data access`);
  }
  if (saas > 0) {
    const cut = clamp(saas * 3, 0, 15);
    tpScore -= cut;
    tpReasons.push(`${saas} externally reachable SaaS portal${saas !== 1 ? 's' : ''}`);
  }
  tpScore = clamp(tpScore);

  // ── 5. Admin Exposure ────────────────────────────────────────────────────────
  let admScore   = 100;
  const admReasons = [];

  // adm.critical / adm.high come from admin_surface_detection module
  const admCritical = adm?.critical ?? 0;
  const admHigh     = adm?.high     ?? 0;
  const admOther    = (adm?.total ?? sc.admin_surfaces) - admCritical - admHigh;

  if (admCritical > 0) {
    const cut = clamp(admCritical * 20, 0, 60);
    admScore -= cut;
    admReasons.push(`${admCritical} critical admin surface${admCritical !== 1 ? 's' : ''} publicly exposed`);
  }
  if (admHigh > 0) {
    const cut = clamp(admHigh * 12, 0, 30);
    admScore -= cut;
    admReasons.push(`${admHigh} high-risk admin surface${admHigh !== 1 ? 's' : ''} publicly exposed`);
  }
  if (admOther > 0) {
    const cut = clamp(admOther * 6, 0, 20);
    admScore -= cut;
    admReasons.push(`${admOther} other management interface${admOther !== 1 ? 's' : ''} exposed`);
  }
  admScore = clamp(admScore);

  // ── Weighted overall ─────────────────────────────────────────────────────────
  // If any category is null (no scan data) it is excluded from the weighted average.
  const categories = [
    { key: 'email_security',    label: 'Email Security',     score: emailScore, weight: 0.20 },
    { key: 'ssl_certificates',  label: 'SSL & Certificates', score: sslScore,   weight: 0.20 },
    { key: 'attack_surface',    label: 'Attack Surface',     score: asScore,    weight: 0.25 },
    { key: 'third_party_risk',  label: 'Third-Party Risk',   score: tpScore,    weight: 0.15 },
    { key: 'admin_exposure',    label: 'Admin Exposure',     score: admScore,   weight: 0.20 },
  ];

  const known = categories.filter(c => c.score !== null);
  const weightSum = known.reduce((s, c) => s + c.weight, 0);
  const overall = weightSum > 0
    ? Math.round(known.reduce((s, c) => s + c.score * (c.weight / weightSum), 0))
    : null;

  // Build per-category objects
  const result = { overall_score: overall };
  const reasonsMap = {
    email_security:   emailReasons,
    ssl_certificates: sslReasons,
    attack_surface:   asReasons,
    third_party_risk: tpReasons,
    admin_exposure:   admReasons,
  };
  for (const { key, score } of categories) {
    const reasons = reasonsMap[key];
    result[key] = {
      score,
      status:  scoreStatus(score),
      reasons: reasons.length > 0 ? reasons : (score === null ? [] : ['No issues detected']),
    };
  }
  return result;
}

// ── Cyber Essentials Readiness v1 ────────────────────────────────────────────
//
// Lightweight UK Cyber Essentials readiness estimate using only existing
// CyberMeters scan and workspace intelligence signals. This is not certification
// logic and does not add new probes, evidence uploads, or compliance tables.

function cyberEssentialsGrade(score) {
  if (score >= 90) return 'A';
  if (score >= 75) return 'B';
  if (score >= 55) return 'C';
  if (score >= 35) return 'D';
  return 'F';
}

function cyberEssentialsStatus(grade) {
  if (grade === 'A' || grade === 'B') return 'likely_ready';
  if (grade === 'C') return 'partially_ready';
  return 'not_ready';
}

function cyberEssentialsCategory(key, label, score, reasons, gaps, recommendations) {
  return {
    key,
    label,
    score: clamp(Math.round(score)),
    weight: 20,
    reasons: reasons.length ? reasons : ['No major readiness gaps detected from available signals.'],
    gaps,
    recommendations,
  };
}

function headerValue(headers, name) {
  if (!headers || typeof headers !== 'object') return null;
  const exact = headers[name] ?? headers[name.toLowerCase()] ?? headers[name.toUpperCase()];
  if (exact !== undefined) return exact;
  const found = Object.entries(headers).find(([k]) => k.toLowerCase() === name.toLowerCase());
  return found ? found[1] : null;
}

function hstsPresent(modules) {
  const hsts = modules?.domain_security_enrichment?.hsts;
  if (hsts && hsts.present !== undefined) return !!hsts.present;
  return !!headerValue(modules?.headers?.headers_observed ?? modules?.headers?.values, 'strict-transport-security');
}

function cspPresent(modules) {
  const value = headerValue(modules?.headers?.headers_observed ?? modules?.headers?.values, 'content-security-policy');
  return !!value;
}

function emailSignals(modules) {
  const email = modules?.email_security ?? {};
  return {
    spf:   !!email.spf?.present,
    dmarc: !!email.dmarc?.present,
    dmarcPolicy: email.dmarc?.policy ?? null,
    dkim:  !!email.dkim?.present,
  };
}

async function getLatestWorkspaceScanReport(wsId, env) {
  try {
    const scan = await env.cybermeters_db
      .prepare(
        `SELECT s.id
         FROM scans s
         LEFT JOIN workspace_domains wd ON wd.domain_id = s.domain_id
         WHERE s.status = 'completed'
           AND (s.workspace_id = ? OR wd.workspace_id = ?)
         ORDER BY s.created_at DESC LIMIT 1`
      )
      .bind(wsId, wsId)
      .first();
    if (!scan?.id) return null;

    const obj = await env.cybermeters_reports.get(`reports/${scan.id}.json`);
    if (!obj) return null;
    return await obj.json();
  } catch {
    return null;
  }
}

async function buildCyberEssentialsReadiness(wsId, env) {
  const [scorecard, report] = await Promise.all([
    buildScorecardData(wsId, env),
    getLatestWorkspaceScanReport(wsId, env),
  ]);
  if (!scorecard) return null;

  const modules = report?.modules ?? {};
  const ssl = modules.ssl ?? {};
  const email = emailSignals(modules);
  const certRisk = scorecard.certificate_risks ?? {};
  const certRiskLevel = certRisk.risk_level ?? null;
  const certDaysLeft = certRisk.days_until_expiry;
  const adminTotal = scorecard.admin_surfaces ?? 0;
  const saasTotal = scorecard.saas_exposures ?? 0;
  const criticalFindings = scorecard.critical_findings ?? 0;
  const highFindings = scorecard.high_findings ?? 0;
  const takeoverRisks = modules.subdomain_takeover?.risks ?? modules.subdomain_takeover?.findings ?? [];
  const takeoverCount = Array.isArray(takeoverRisks) ? takeoverRisks.length : 0;
  const hsts = hstsPresent(modules);
  const csp = cspPresent(modules);

  const categories = [];
  const allGaps = [];
  const allRecommendations = [];

  function addGap(state, amount, reason, recommendation) {
    state.score -= amount;
    state.reasons.push(reason);
    state.gaps.push(reason);
    state.recommendations.push(recommendation ?? reason);
    allGaps.push({ reason, impact: amount });
    allRecommendations.push(recommendation ?? reason);
  }

  function addReason(state, reason) {
    state.reasons.push(reason);
  }

  // Boundary Protection: HTTPS, headers, exposed critical assets, takeover risk.
  {
    const state = { score: 100, reasons: [], gaps: [], recommendations: [] };
    if (ssl.https_available === false) {
      addGap(state, 30, 'HTTPS is not confirmed for the latest scanned domain.', 'Enable HTTPS on all public web services.');
    } else if (ssl.https_available === true) {
      addReason(state, 'HTTPS is available on the latest scanned domain.');
    }
    if (!hsts && !csp) {
      addGap(state, 15, 'Core browser boundary headers are missing or not confirmed.', 'Configure HSTS and Content Security Policy where applicable.');
    }
    if (criticalFindings > 0) {
      addGap(state, 20, `${criticalFindings} critical finding${criticalFindings !== 1 ? 's' : ''} remain in the latest scan.`, 'Remediate critical external findings before assessment.');
    }
    if (adminTotal > 0) {
      addGap(state, 20, `${adminTotal} exposed admin or management surface${adminTotal !== 1 ? 's' : ''} detected.`, 'Restrict admin and management interfaces from public internet access.');
    }
    if (takeoverCount > 0) {
      addGap(state, 25, `${takeoverCount} potential subdomain takeover risk${takeoverCount !== 1 ? 's' : ''} detected.`, 'Remove dangling DNS records or reclaim the referenced services.');
    }
    categories.push(cyberEssentialsCategory('boundary_protection', 'Boundary Protection', state.score, state.reasons, state.gaps, state.recommendations));
  }

  // Secure Configuration: HSTS, CSP, TLS posture, certificate health.
  {
    const state = { score: 100, reasons: [], gaps: [], recommendations: [] };
    if (!hsts) {
      addGap(state, 25, 'HSTS is not present or could not be confirmed.', 'Enable HSTS after validating HTTPS coverage.');
    } else {
      addReason(state, 'HSTS is present.');
    }
    if (!csp) {
      addGap(state, 20, 'Content Security Policy is not present or could not be confirmed.', 'Add a Content Security Policy suitable for the application.');
    } else {
      addReason(state, 'Content Security Policy is present.');
    }
    if (ssl.http_redirects_to_https === false) {
      addGap(state, 15, 'HTTP to HTTPS redirect is not confirmed.', 'Redirect all HTTP traffic to HTTPS.');
    }
    if (ssl.https_available === false) {
      addGap(state, 25, 'TLS is not available on the latest scanned domain.', 'Deploy valid TLS certificates for public services.');
    }
    if (certRiskLevel === 'critical' || certRiskLevel === 'high') {
      addGap(state, certRiskLevel === 'critical' ? 25 : 15, `Certificate intelligence risk is ${certRiskLevel}.`, 'Review certificate expiry, issuer, and suspicious certificate signals.');
    }
    categories.push(cyberEssentialsCategory('secure_configuration', 'Secure Configuration', state.score, state.reasons, state.gaps, state.recommendations));
  }

  // Access Control: email authentication plus externally visible admin/SaaS portals.
  {
    const state = { score: 100, reasons: [], gaps: [], recommendations: [] };
    if (!email.spf) addGap(state, 15, 'SPF is missing or not confirmed.', 'Publish an SPF record for approved sending services.');
    else addReason(state, 'SPF is present.');
    if (!email.dmarc) {
      addGap(state, 25, 'DMARC is missing or not confirmed.', 'Publish a DMARC policy for the domain.');
    } else if (email.dmarcPolicy === 'none') {
      addGap(state, 10, 'DMARC is monitor-only (p=none).', 'Move DMARC toward quarantine or reject after monitoring.');
    } else {
      addReason(state, 'DMARC is present.');
    }
    if (!email.dkim) addReason(state, 'DKIM could not be verified using common selectors; a custom selector may be in use.');
    else addReason(state, 'DKIM is detected.');
    if (adminTotal > 0) addGap(state, 25, 'Public admin surfaces increase access-control exposure.', 'Place admin portals behind VPN, SSO, or IP allowlists.');
    if (saasTotal > 0) addGap(state, 10, `${saasTotal} externally reachable SaaS portal${saasTotal !== 1 ? 's' : ''} detected.`, 'Review SSO and MFA coverage for externally reachable SaaS portals.');
    categories.push(cyberEssentialsCategory('access_control', 'Access Control', state.score, state.reasons, state.gaps, state.recommendations));
  }

  // Phishing & Malware Exposure: estimate only, based on proxy domain/email posture.
  {
    const state = { score: 100, reasons: [], gaps: [], recommendations: [] };
    addReason(state, 'Phishing and malware exposure is estimated from available domain, email, and external exposure signals only.');
    if (!email.dmarc || email.dmarcPolicy === 'none') {
      addGap(state, 25, 'Email anti-spoofing enforcement is weak.', 'Strengthen DMARC enforcement to reduce spoofing and phishing exposure.');
    }
    if (!email.spf) addGap(state, 15, 'SPF is missing or not confirmed.', 'Limit authorized mail senders with SPF.');
    if (!email.dkim) addReason(state, 'DKIM could not be verified using common selectors; a custom selector may be in use.');
    if (criticalFindings + highFindings > 0) {
      addGap(state, 15, 'High-impact external findings may increase malware delivery risk.', 'Prioritize remediation of critical and high findings.');
    }
    categories.push(cyberEssentialsCategory('malware_protection', 'Phishing & Malware Exposure', state.score, state.reasons, state.gaps, state.recommendations));
  }

  // Patch Management Readiness: certificate expiry, trend, remediation backlog.
  {
    const state = { score: 100, reasons: [], gaps: [], recommendations: [] };
    if (typeof certDaysLeft === 'number') {
      if (certDaysLeft < 0) {
        addGap(state, 30, 'A certificate is expired.', 'Renew expired certificates immediately.');
      } else if (certDaysLeft < 30) {
        addGap(state, 15, `A certificate expires in ${certDaysLeft} day${certDaysLeft !== 1 ? 's' : ''}.`, 'Renew certificates before the 30-day window.');
      } else {
        addReason(state, 'Certificate expiry health is acceptable.');
      }
    }
    if (certRiskLevel === 'critical' || certRiskLevel === 'high') {
      addGap(state, 15, `Certificate risk level is ${certRiskLevel}.`, 'Investigate certificate intelligence findings.');
    }
    if (criticalFindings > 0 || highFindings > 0) {
      addGap(state, 25, `${criticalFindings + highFindings} critical/high finding${criticalFindings + highFindings !== 1 ? 's' : ''} remain open in the latest scan.`, 'Close critical and high findings as evidence of remediation responsiveness.');
    } else {
      addReason(state, 'No critical or high findings in the latest scan.');
    }
    if ((scorecard.asset_events_30d ?? 0) > 0) {
      addReason(state, `${scorecard.asset_events_30d} asset change event${scorecard.asset_events_30d !== 1 ? 's' : ''} recorded in the last 30 days.`);
    }
    categories.push(cyberEssentialsCategory('patch_management_readiness', 'Patch Management Readiness', state.score, state.reasons, state.gaps, state.recommendations));
  }

  const score = Math.round(categories.reduce((sum, c) => sum + c.score * (c.weight / 100), 0));
  const grade = cyberEssentialsGrade(score);
  const topGaps = [...new Map(
    allGaps
      .sort((a, b) => b.impact - a.impact)
      .map(g => [g.reason, g.reason])
  ).values()].slice(0, 5);
  const recommendations = [...new Set(allRecommendations)].slice(0, 6);

  return {
    workspace_id: wsId,
    workspace_name: scorecard.workspace_name,
    score,
    grade,
    status: cyberEssentialsStatus(grade),
    categories,
    top_gaps: topGaps,
    recommendations,
    summary: topGaps.length
      ? `Cyber Essentials readiness is ${cyberEssentialsStatus(grade).replace(/_/g, ' ')}. Focus first on ${topGaps.slice(0, 2).join(' and ')}`
      : 'Cyber Essentials readiness looks strong from currently available CyberMeters signals.',
    generated_at: new Date().toISOString(),
    latest_scan: {
      domain: scorecard.last_scanned_domain,
      scanned_at: scorecard.last_scan_at,
      security_score: scorecard.security_score,
      risk_rating: scorecard.risk_rating,
    },
    limitations: [
      'CyberMeters does not certify Cyber Essentials.',
      'This readiness estimate uses externally observable CyberMeters signals only.',
      'Endpoint protection, internal device configuration, and user access policies cannot be fully assessed from external ASM data.',
    ],
  };
}

// ── Supply Chain, Resilience & Third-Party Risk Engine ───────────────────────
//
// Intelligence-layer only. No new scanning. Uses existing data from:
//   - workspace_vendors  (all source_modules)
//   - workspace_assets
//   - workspace_brs_scores
//   - R2 scan report JSON (modules.subdomains, modules.third_party_assets)
//
// Compliance readiness: low/medium/high confidence only. No legal assertions.
// Does not rewrite Vendor Risk Engine or BRS Engine.

