  'azure':         'Microsoft',
  'office365':     'Microsoft',
  'linkedin':      'Microsoft',
  'github':        'Microsoft',
  'outlook':       'Microsoft',
  'live':          'Microsoft',
  'hotmail':       'Microsoft',
  // Amazon / AWS
  'amazon':        'Amazon',
  'aws':           'Amazon',
  'cloudfront':    'Amazon',
  's3':            'Amazon',
  'amazonaws':     'Amazon',
  // Cloudflare
  'cloudflare':    'Cloudflare',
  // Akamai
  'akamai':        'Akamai',
  'linode':        'Akamai',
  // Salesforce
  'salesforce':    'Salesforce',
  'heroku':        'Salesforce',
