// ── Vendor tier classification rules ────────────────────────────────────────
// Tier 1 = critical direct dependency (authentication, payments, core infra)
// Tier 2 = significant but not immediately critical (analytics, CRM, CDN)
// Tier 3 = low criticality (marketing, social, misc SaaS)
const VENDOR_TIER_RULES = {
  tier1_categories: ['identity_provider', 'payments', 'infrastructure', 'certificate_authority'],
  tier2_categories: ['cloud', 'hosting', 'cdn', 'security', 'email_identity', 'collaboration'],
  tier3_categories: ['analytics', 'crm', 'saas', 'support', 'ecommerce', 'social', 'identity'],
  tier1_risk_levels: ['high'],
  tier2_risk_levels: ['medium'],
};

/**
 * enrichVendors(vendors)
 *
 * Adds parent_company and tier fields to each vendor object.
 * Pure function — no I/O.
 */
function enrichVendors(vendors) {
  return vendors.map(v => {
    const nameKey = (v.vendor_name || '').toLowerCase().replace(/[\s.-]/g, '');
    let parent = null;
    for (const [key, corp] of Object.entries(PARENT_COMPANY_MAP)) {
      if (nameKey.includes(key)) { parent = corp; break; }
    }

    let tier;
    const cat = v.category || '';
    const risk = v.risk_level || '';
    if (VENDOR_TIER_RULES.tier1_categories.includes(cat) ||
        (VENDOR_TIER_RULES.tier1_risk_levels.includes(risk) && cat !== 'certificate_authority')) {
      tier = 1;
    } else if (VENDOR_TIER_RULES.tier2_categories.includes(cat)) {
      tier = 2;
    } else {
      tier = 3;
    }

    return { ...v, parent_company: parent, tier };
  });
}

/**
 * buildDependencyGraph(enrichedVendors)
 *
 * Returns a simplified dependency graph keyed by parent company (or vendor name).
 * Each node carries: tier, categories[], vendor_count, risk_levels[]
 */
function buildDependencyGraph(enrichedVendors) {
  const graph = {};
  for (const v of enrichedVendors) {
    const key = v.parent_company || v.vendor_name || 'Unknown';
    if (!graph[key]) {
      graph[key] = { tier: v.tier, categories: [], vendor_count: 0, risk_levels: [], vendors: [] };
    }
    const node = graph[key];
    node.vendor_count += 1;
    node.vendors.push(v.vendor_name);
    if (!node.categories.includes(v.category)) node.categories.push(v.category);
    if (!node.risk_levels.includes(v.risk_level)) node.risk_levels.push(v.risk_level);
    // Promote tier to highest (lowest number) seen
    if (v.tier < node.tier) node.tier = v.tier;
  }
  return graph;
}

/**
 * computeConcentration(graph, activeVendors)
 *
 * Detects concentration risk based on parent-company consolidation.
 * Returns { level, spofs, top_parents, concentration_score }
 */
function computeConcentration(graph, activeVendors) {
  const total = activeVendors.length;
  if (total === 0) return { level: 'low', spofs: [], top_parents: [], concentration_score: 100 };

  const entries = Object.entries(graph).sort((a, b) => b[1].vendor_count - a[1].vendor_count);
  const top3Share = entries.slice(0, 3).reduce((s, [, n]) => s + n.vendor_count, 0) / total;

  const tier1Parents = entries.filter(([, n]) => n.tier === 1);
  const spofs = tier1Parents
    .filter(([, n]) => n.vendor_count === 1 || n.categories.some(c => ['identity_provider','payments'].includes(c)))
    .map(([name]) => name);

  let level;
  if (top3Share > 0.7 || spofs.length >= 3) level = 'critical';
  else if (top3Share > 0.5 || spofs.length >= 2) level = 'high';
  else if (top3Share > 0.3 || spofs.length >= 1) level = 'medium';
  else level = 'low';

  const concentration_score = Math.max(0, 100 - Math.round(top3Share * 60) - spofs.length * 10);

  return {
    level,
    spofs,
    top_parents: entries.slice(0, 5).map(([name, n]) => ({ name, tier: n.tier, vendor_count: n.vendor_count, categories: n.categories })),
    concentration_score,
  };
}

/**
 * computeCascadingRisks(enrichedVendors, graph)
 *
 * Identifies potential cascade failure scenarios.
 * Returns array of risk objects: { scenario, affected_categories, severity, likelihood }
 */
function computeCascadingRisks(enrichedVendors, graph) {
  const risks = [];

  // Identity provider failure → auth collapse
  const idpVendors = enrichedVendors.filter(v => v.category === 'identity_provider' && v.status === 'active');
  if (idpVendors.length === 1) {
    risks.push({
      scenario: 'Single identity provider — authentication single point of failure',
      affected_categories: ['identity_provider'],
      severity: 'critical',
      likelihood: 'medium',
      vendors: idpVendors.map(v => v.vendor_name),
    });
  }

  // Payment processor failure
  const paymentVendors = enrichedVendors.filter(v => v.category === 'payments' && v.status === 'active');
  if (paymentVendors.length === 1) {
    risks.push({
      scenario: 'Single payment processor — revenue collection risk',
      affected_categories: ['payments'],
      severity: 'high',
      likelihood: 'low',
      vendors: paymentVendors.map(v => v.vendor_name),
    });
  }

  // Certificate authority concentration
  const caVendors = enrichedVendors.filter(v => v.category === 'certificate_authority' && v.status === 'active');
  const caParents = [...new Set(caVendors.map(v => v.parent_company || v.vendor_name))];
  if (caParents.length === 1 && caVendors.length >= 2) {
    risks.push({
      scenario: 'All SSL certificates from a single certificate authority',
      affected_categories: ['certificate_authority'],
      severity: 'medium',
      likelihood: 'low',
      vendors: caVendors.map(v => v.vendor_name),
    });
  }

  // Cloud / hosting concentration
  const infraVendors = enrichedVendors.filter(v => ['cloud','hosting','infrastructure'].includes(v.category) && v.status === 'active');
  const infraParents = [...new Set(infraVendors.map(v => v.parent_company || v.vendor_name))];
  if (infraVendors.length >= 2 && infraParents.length === 1) {
    risks.push({
      scenario: 'Cloud and hosting concentrated on a single provider',
      affected_categories: ['cloud', 'hosting', 'infrastructure'],
      severity: 'high',
      likelihood: 'low',
      vendors: infraVendors.map(v => v.vendor_name),
    });
  }

  // High-risk vendor count
  const highRiskActive = enrichedVendors.filter(v => v.risk_level === 'high' && v.status === 'active' && v.source_module === 'vendor_risk');
  if (highRiskActive.length >= 5) {
    risks.push({
      scenario: `${highRiskActive.length} high-risk vendors detected — elevated aggregate risk`,
      affected_categories: [...new Set(highRiskActive.map(v => v.category))],
      severity: 'high',
      likelihood: 'medium',
      vendors: highRiskActive.slice(0, 5).map(v => v.vendor_name),
    });
  }

  return risks;
}

/**
 * computeOperationalResilience(enrichedVendors, cascadingRisks, concentration)
 *
 * Produces a 0-100 resilience score.
 * Higher = more resilient.
 */
function computeOperationalResilience(enrichedVendors, cascadingRisks, concentration) {
  let score = 100;

  // Penalise for single points of failure
  score -= concentration.spofs.length * 12;

  // Penalise for cascading risk severity
  for (const r of cascadingRisks) {
    if (r.severity === 'critical') score -= 20;
    else if (r.severity === 'high') score -= 12;
    else if (r.severity === 'medium') score -= 6;
  }

  // Penalise for concentration level
  if (concentration.level === 'critical') score -= 20;
  else if (concentration.level === 'high') score -= 12;
  else if (concentration.level === 'medium') score -= 6;

  // Penalise for high-risk tier-1 vendors
  const highRiskTier1 = enrichedVendors.filter(v => v.tier === 1 && v.risk_level === 'high' && v.status === 'active');
  score -= highRiskTier1.length * 8;

  return Math.max(0, Math.min(100, score));
}

/**
 * computeComplianceReadiness(enrichedVendors, brsScore)
 *
 * Returns confidence signals for common compliance frameworks.
 * Outputs: low | medium | high — no legal assertions.
 */
function computeComplianceReadiness(enrichedVendors, brsScore) {
  const active = enrichedVendors.filter(v => v.status === 'active');

  // GDPR readiness signals
  const hasIdp = active.some(v => v.category === 'identity_provider');
  const highRiskCount = active.filter(v => v.risk_level === 'high').length;
  const euSignals = active.filter(v => {
    const n = (v.vendor_name || '').toLowerCase();
    return n.includes('eu') || n.includes('europe') || n.includes('gdpr');
  }).length;
  let gdpr = 'low';
  if (hasIdp && highRiskCount === 0 && brsScore >= 70) gdpr = 'high';
  else if (highRiskCount <= 2 && brsScore >= 50) gdpr = 'medium';

  // ISO 27001 / security governance signals
  const hasSecurityVendors = active.some(v => v.category === 'security');
  const hasCaVendors = active.some(v => v.category === 'certificate_authority');
  let security_governance = 'low';
  if (hasSecurityVendors && hasCaVendors && brsScore >= 75) security_governance = 'high';
  else if (hasCaVendors && brsScore >= 55) security_governance = 'medium';

  // PCI-DSS readiness signals
  const hasPayments = active.some(v => v.category === 'payments');
  const paymentHighRisk = active.filter(v => v.category === 'payments' && v.risk_level === 'high').length;
  let pci_dss = 'low';
  if (hasPayments && paymentHighRisk === 0 && brsScore >= 70) pci_dss = 'medium';
  else if (!hasPayments) pci_dss = 'medium'; // no payment processors detected = less exposure

  return {
    gdpr,
    security_governance,
    pci_dss,
    note: 'Confidence signals only. CyberMeters does not certify compliance. Engage a qualified assessor for formal certification.',
  };
}

/**
 * computeAsmMaturity(workspaceData)
 *
 * Estimates ASM programme maturity from available workspace signals.
 * Returns { level: 'initial'|'developing'|'defined'|'managed'|'optimising', score: 0-100 }
 */
function computeAsmMaturity(workspaceData) {
  let score = 0;
  const { total_scans = 0, total_vendors = 0, total_assets = 0, brs_score = 0 } = workspaceData;

  // Scan cadence
  if (total_scans >= 20) score += 25;
  else if (total_scans >= 10) score += 15;
  else if (total_scans >= 3) score += 8;
  else if (total_scans >= 1) score += 3;

  // Vendor visibility
  if (total_vendors >= 20) score += 20;
  else if (total_vendors >= 10) score += 12;
  else if (total_vendors >= 3) score += 6;

  // Asset visibility
  if (total_assets >= 50) score += 20;
  else if (total_assets >= 20) score += 12;
  else if (total_assets >= 5) score += 6;

  // Security posture
  if (brs_score >= 80) score += 35;
  else if (brs_score >= 65) score += 25;
  else if (brs_score >= 50) score += 15;
  else if (brs_score >= 30) score += 8;

  const level =
    score >= 80 ? 'optimising' :
    score >= 60 ? 'managed' :
    score >= 40 ? 'defined' :
    score >= 20 ? 'developing' :
    'initial';

  return { level, score: Math.min(100, score) };
}

function computeDnsResilienceSignalsFromVendors(activeVendors) {
  const dnsVendors = activeVendors.filter((v) => {
    const cat = normalizeVendorRiskCategory(v.category, v.vendor_name, v.source);
    const name = String(v.vendor_name || "").toLowerCase();
    return cat === "dns_provider" || /cloudflare|route ?53|awsdns|azure dns|google cloud dns|akamai|fastly/.test(name);
  });
  const caVendors = activeVendors.filter((v) => {
    const cat = String(v.category || "").toLowerCase();
    return cat === "certificate_authority" || cat === "security_tooling";
  });

  const dnsProviders = [...new Set(dnsVendors.map((v) => v.vendor_name).filter(Boolean))];
  const caProviders = [...new Set(caVendors.map((v) => v.vendor_name).filter(Boolean))];

  return {
    dns_provider_concentration: {
      provider_count: dnsProviders.length,
      providers: dnsProviders,
      dependency:
        dnsProviders.length === 0 ? "unknown" :
        dnsProviders.length === 1 ? "single-provider dependency" : "multi-provider dependency",
      label:
        dnsProviders.length === 1 ? `${dnsProviders[0]}-only` :
        dnsProviders.length > 1 ? "Multi-provider" : "Unknown",
    },
    certificate_authority_concentration: {
      provider_count: caProviders.length,
      providers: caProviders,
      dependency:
        caProviders.length === 0 ? "unknown" :
        caProviders.length === 1 ? "single_ca_dependency" : "multiple_ca_usage",
    },
    source: "workspace_vendors",
  };
}

/**
 * computeSupplyChainIntelligence(wsId, env)
 *
 * Orchestrates all supply chain intelligence computations.
 * Reads from D1 only (no R2 needed for this sprint).
 * Returns full intelligence payload or null on error.
 */
async function computeSupplyChainIntelligence(wsId, env) {
  try {
    // ── Load vendors and workspace context from D1 ──────────────────────────
    const [vendorRows, wsRow, brsRow, assetRow, scanRow] = await Promise.all([
      env.cybermeters_db.prepare(
        `SELECT vendor_name, category, risk_level, status, source_module, confidence, first_seen, last_seen
         FROM workspace_vendors
         WHERE workspace_id = ?`
      ).bind(wsId).all().then(r => r.results || []),

      env.cybermeters_db.prepare(`SELECT id, name FROM workspaces WHERE id = ?`).bind(wsId).first(),

      env.cybermeters_db.prepare(
        `SELECT score AS brs_score FROM workspace_brs_scores WHERE workspace_id = ? ORDER BY calculated_at DESC LIMIT 1`
      ).bind(wsId).first(),

      env.cybermeters_db.prepare(
        `SELECT COUNT(*) AS cnt FROM workspace_assets WHERE workspace_id = ? AND status = 'active'`
      ).bind(wsId).first(),

      env.cybermeters_db.prepare(
        `SELECT COUNT(*) AS cnt FROM scans WHERE workspace_id = ?`
      ).bind(wsId).first(),
    ]);

    const brsScore = brsRow?.brs_score ?? 0;
    const activeVendors = vendorRows.filter(v => v.status === 'active');
    const enriched = enrichVendors(activeVendors);

    const workspaceData = {
      total_scans:   scanRow?.cnt ?? 0,
      total_vendors: activeVendors.length,
      total_assets:  assetRow?.cnt ?? 0,
      brs_score:     brsScore,
    };

    // ── Core computations ───────────────────────────────────────────────────
    const graph           = buildDependencyGraph(enriched);
    const concentration   = computeConcentration(graph, activeVendors);
    const cascadingRisks  = computeCascadingRisks(enriched, graph);
    const resilienceScore = computeOperationalResilience(enriched, cascadingRisks, concentration);
    const dnsResilienceSignals = computeDnsResilienceSignalsFromVendors(activeVendors);
    const compliance      = computeComplianceReadiness(enriched, brsScore);
    const asmMaturity     = computeAsmMaturity(workspaceData);

    // ── Supply chain score (composite) ─────────────────────────────────────
    const concentrationScore = concentration.concentration_score;
    const vendorRiskPenalty  = Math.min(40, enriched.filter(v => v.risk_level === 'high' && v.source_module === 'vendor_risk').length * 5);
    const supplyChainScore   = Math.max(0, Math.round(
      concentrationScore * 0.4 +
      resilienceScore    * 0.35 +
      asmMaturity.score  * 0.25 -
      vendorRiskPenalty
    ));

    // ── Tier counts ─────────────────────────────────────────────────────────
    const tier1Count = enriched.filter(v => v.tier === 1).length;
    const tier2Count = enriched.filter(v => v.tier === 2).length;
    const tier3Count = enriched.filter(v => v.tier === 3).length;

    // ── Critical vendors list ───────────────────────────────────────────────
    const criticalVendors = enriched
      .filter(v => v.tier === 1 || v.risk_level === 'high')
      .map(v => ({
        name:           v.vendor_name,
        category:       v.category,
        tier:           v.tier,
        risk_level:     v.risk_level,
        parent_company: v.parent_company,
        source_module:  v.source_module,
      }));

    const payload = {
      supply_chain_score:          supplyChainScore,
      operational_resilience_score: resilienceScore,
      concentration_level:         concentration.level,
      critical_vendor_count:       criticalVendors.length,
      tier1_count:                 tier1Count,
      tier2_count:                 tier2Count,
      tier3_count:                 tier3Count,
      spof_count:                  concentration.spofs.length,
      critical_vendors:            criticalVendors,
      dependency_graph:            graph,
      cascading_risks:             cascadingRisks,
      concentration:               concentration,
      dns_resilience_signals:       dnsResilienceSignals,
      compliance_readiness:        compliance,
      asm_maturity:                asmMaturity,
      vendor_summary: {
        total:   vendorRows.length,
        active:  activeVendors.length,
        high:    enriched.filter(v => v.risk_level === 'high').length,
        medium:  enriched.filter(v => v.risk_level === 'medium').length,
        low:     enriched.filter(v => v.risk_level === 'low').length,
      },
      workspace: { id: wsId, name: wsRow?.name ?? '' },
      brs_score: brsScore,
      calculated_at: new Date().toISOString(),
    };

    return payload;
  } catch (err) {
    console.error('[supply-chain] computeSupplyChainIntelligence error:', err);
    return null;
  }
}

/**
 * upsertSupplyChainScore(wsId, payload, env)
 *
 * Persists latest supply chain intelligence to D1 and appends history row.
 * Called from Phase 8i in scan completion pipeline.
 */
async function upsertSupplyChainScore(wsId, payload, env) {
  if (!payload) return;
  const now = new Date().toISOString();
  const id  = crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).slice(2);
  const hid = crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).slice(2);

  await env.cybermeters_db.batch([
    env.cybermeters_db.prepare(`
      INSERT INTO workspace_supply_chain_scores
        (id, workspace_id, supply_chain_score, resilience_score, concentration_level,
         critical_vendor_count, tier1_count, tier2_count, tier3_count, spof_count,
         payload_json, calculated_at, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(workspace_id) DO UPDATE SET
        supply_chain_score    = excluded.supply_chain_score,
        resilience_score      = excluded.resilience_score,
        concentration_level   = excluded.concentration_level,
        critical_vendor_count = excluded.critical_vendor_count,
        tier1_count           = excluded.tier1_count,
        tier2_count           = excluded.tier2_count,
        tier3_count           = excluded.tier3_count,
        spof_count            = excluded.spof_count,
        payload_json          = excluded.payload_json,
        calculated_at         = excluded.calculated_at,
        updated_at            = excluded.updated_at
    `).bind(
      id, wsId,
      payload.supply_chain_score,
      payload.operational_resilience_score,
      payload.concentration_level,
      payload.critical_vendor_count,
      payload.tier1_count,
      payload.tier2_count,
      payload.tier3_count,
      payload.spof_count,
      JSON.stringify(payload),
      payload.calculated_at,
      now, now
    ),

    env.cybermeters_db.prepare(`
      INSERT INTO workspace_supply_chain_history
        (id, workspace_id, supply_chain_score, resilience_score, concentration_level,
         critical_vendor_count, spof_count, calculated_at, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      hid, wsId,
      payload.supply_chain_score,
      payload.operational_resilience_score,
      payload.concentration_level,
      payload.critical_vendor_count,
      payload.spof_count,
      payload.calculated_at,
      now
    ),
  ]);
}

// ── End Supply Chain Intelligence Engine ─────────────────────────────────────

/**
 * buildScorecardData(wsId, env)
 *
 * Returns the full scorecard object for the workspace, or null on DB error.
 * Uses:
 *   - D1 batch 1  — workspace meta, asset / vendor / brand counts
 *   - D1 batch 2  — findings severity + top remediation (needs scan_id)
 *   - R2 (1 get)  — module-level data (saas_exposure, admin_surface_detection,
 *                    certificate_intelligence, third_party_assets, cloud assets)
 */
async function buildScorecardData(wsId, env) {
  const now30dAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();

  // ── D1 Batch 1 ─────────────────────────────────────────────────────────────
  let b1;
  try {
    b1 = await env.cybermeters_db.batch([
      // 0. Latest completed scan
      env.cybermeters_db.prepare(
        `SELECT s.id, s.score, s.rating, s.domain, s.created_at
         FROM workspace_domains wd
         JOIN domains d ON d.id = wd.domain_id
         JOIN scans   s ON s.domain_id = d.id
         WHERE wd.workspace_id = ? AND s.status = 'completed'
         ORDER BY s.created_at DESC LIMIT 1`
      ).bind(wsId),

      // 1. Workspace name
      env.cybermeters_db.prepare(
        `SELECT name FROM workspaces WHERE id = ?`
      ).bind(wsId),

      // 2. Active asset count
      env.cybermeters_db.prepare(
        `SELECT COUNT(*) AS n FROM workspace_assets WHERE workspace_id = ? AND status = 'active'`
      ).bind(wsId),

      // 3. Asset type breakdown (admin_panel, cloud_storage, etc.)
      env.cybermeters_db.prepare(
        `SELECT asset_type, COUNT(*) AS n FROM workspace_assets
         WHERE workspace_id = ? AND status = 'active' GROUP BY asset_type`
      ).bind(wsId),

      // 4. Active vendor count
      env.cybermeters_db.prepare(
        `SELECT COUNT(*) AS n FROM workspace_vendors WHERE workspace_id = ? AND status = 'active'`
      ).bind(wsId),

      // 5. Vendor risk breakdown
      env.cybermeters_db.prepare(
        `SELECT risk_level, COUNT(*) AS n FROM workspace_vendors
         WHERE workspace_id = ? AND status = 'active' GROUP BY risk_level`
      ).bind(wsId),

      // 6. Active brand risks (DNS-confirmed typosquats, status='active')
      env.cybermeters_db.prepare(
        `SELECT risk_level, COUNT(*) AS n FROM workspace_brand_assets
         WHERE workspace_id = ? AND status = 'active' GROUP BY risk_level`
      ).bind(wsId),

      // 7. Total brand candidates (any status)
      env.cybermeters_db.prepare(
        `SELECT COUNT(*) AS n FROM workspace_brand_assets WHERE workspace_id = ?`
      ).bind(wsId),

      // 8. Asset events in last 30 days
      env.cybermeters_db.prepare(
        `SELECT COUNT(*) AS n FROM asset_events WHERE workspace_id = ? AND created_at >= ?`
      ).bind(wsId, now30dAgo),

      // 9. New assets discovered in last 30 days (first_seen)
      env.cybermeters_db.prepare(
        `SELECT COUNT(*) AS n FROM workspace_assets
         WHERE workspace_id = ? AND first_seen >= ?`
      ).bind(wsId, now30dAgo),

      // 10. Total domains in workspace
      env.cybermeters_db.prepare(
        `SELECT COUNT(*) AS n FROM workspace_domains WHERE workspace_id = ?`
      ).bind(wsId),
    ]);
  } catch {
    return null;
  }

  const latestScan     = b1[0].results?.[0]  ?? null;
  const wsName         = b1[1].results?.[0]?.name ?? 'Unknown';
  const activeAssets   = b1[2].results?.[0]?.n    ?? 0;
  const assetTypeRows  = b1[3].results ?? [];
  const vendorsActive  = b1[4].results?.[0]?.n ?? 0;
  const vendorRiskRows = b1[5].results ?? [];
  const brandRiskRows  = b1[6].results ?? [];
  const brandTotal     = b1[7].results?.[0]?.n ?? 0;
  const events30d      = b1[8].results?.[0]?.n ?? 0;
  const newAssets30d   = b1[9].results?.[0]?.n ?? 0;
  const totalDomains   = b1[10].results?.[0]?.n ?? 0;

  // ── D1 Batch 2: scan-specific data ────────────────────────────────────────
  const scanId = latestScan?.id ?? null;
  let criticalFindings = 0, highFindings = 0, mediumFindings = 0, lowFindings = 0;
  let topRemediation   = [];

  if (scanId) {
    try {
      const b2 = await env.cybermeters_db.batch([
        env.cybermeters_db.prepare(
          `SELECT severity, COUNT(*) AS n FROM findings WHERE scan_id = ? GROUP BY severity`
        ).bind(scanId),
        env.cybermeters_db.prepare(
          `SELECT title, priority, action FROM remediation_items
           WHERE scan_id = ? ORDER BY priority ASC LIMIT 5`
        ).bind(scanId),
      ]);
      const sevMap = Object.fromEntries((b2[0].results ?? []).map(r => [r.severity, r.n]));
      criticalFindings = sevMap.critical ?? 0;
      highFindings     = sevMap.high     ?? 0;
      mediumFindings   = sevMap.medium   ?? 0;
      lowFindings      = sevMap.low      ?? 0;
      topRemediation   = (b2[1].results ?? []).map(r => ({
        title:       r.title,
        priority:    Number(r.priority),
        description: r.action,
      }));
    } catch { /* non-fatal — findings unavailable */ }
  }

  // ── R2: latest scan report for module-level data (1 subrequest) ───────────
  let report = null;
  if (scanId) {
    try {
      const obj = await env.cybermeters_reports.get(`reports/${scanId}.json`);
      if (obj) report = await obj.json();
    } catch { /* tolerate missing report */ }
  }

  // Derived values from R2 modules
  const saasTotal      = report?.modules?.saas_exposure?.total ?? 0;
  const adminTotal     = report?.modules?.admin_surface_detection?.total ?? 0;
  const certRiskLevel  = report?.modules?.certificate_intelligence?.certificate_risk_level ?? null;
  const certSignals    = report?.modules?.certificate_intelligence?.suspicious_certificate_signals ?? [];
  const certDaysLeft   = report?.modules?.certificate_intelligence?.days_until_expiry ?? null;
  const tpaTotal       = report?.modules?.third_party_assets?.total ?? 0;
  const cloudAssetList = report?.modules?.cloud_storage_discovery?.assets ?? [];

  // Computed helpers
  const assetTypeMap  = Object.fromEntries(assetTypeRows.map(r => [r.asset_type, r.n]));
  const vendorRiskMap = Object.fromEntries(vendorRiskRows.map(r => [r.risk_level, r.n]));
  const brandRiskMap  = Object.fromEntries(brandRiskRows.map(r => [r.risk_level, r.n]));
  const brandHighRisk = brandRiskMap.high   ?? 0;
  const brandMedRisk  = brandRiskMap.medium ?? 0;
  const activeBrands  = brandHighRisk + brandMedRisk + (brandRiskMap.low ?? 0);

  // ── Executive Summary ──────────────────────────────────────────────────────
  const good              = [];
  const attentionRequired = [];
  const urgent            = [];

  // ── Good signals ──────────────────────────────────────────────────────────
  if (activeAssets > 0) {
    good.push(
      `Asset inventory is active — ${activeAssets} asset${activeAssets !== 1 ? 's' : ''} monitored across ${totalDomains} domain${totalDomains !== 1 ? 's' : ''}.`
    );
  }
  if (!cloudAssetList.length && !assetTypeMap['cloud_storage']) {
    good.push('No cloud storage exposure was detected.');
  }
  if (vendorsActive > 0) {
    good.push(
      `Vendor dependencies are visible — ${vendorsActive} third-party vendor${vendorsActive !== 1 ? 's' : ''} detected.`
    );
  }
  if (criticalFindings === 0 && highFindings === 0) {
    good.push('No critical or high-severity findings in the latest scan.');
  }
  if (brandHighRisk === 0 && activeBrands === 0) {
    good.push('No active brand impersonation domains detected.');
  }
  if (adminTotal === 0) {
    good.push('No exposed admin or management surfaces detected.');
  }
  if (certRiskLevel === 'low' || (certRiskLevel === null && certSignals.length === 0)) {
    good.push('Certificate health looks normal — no suspicious signals detected.');
  }

  // ── Attention Required ────────────────────────────────────────────────────
  if (events30d > 0) {
    attentionRequired.push(
      `Attack surface changed in the last 30 days — ${events30d} asset event${events30d !== 1 ? 's' : ''} recorded.`
    );
  }
  if (newAssets30d > 0) {
    attentionRequired.push(
      `${newAssets30d} new asset${newAssets30d !== 1 ? 's' : ''} discovered in the last 30 days.`
    );
  }
  if (tpaTotal > 0) {
    attentionRequired.push(
      `${tpaTotal} third-party service${tpaTotal !== 1 ? 's' : ''} in use — email, support, or marketing tools with external data access.`
    );
  }
  if (certSignals.length > 0 && certRiskLevel !== 'critical') {
    const sigPreview = certSignals
      .slice(0, 2)
      .map((sig) => typeof sig === 'string' ? sig : (sig.description || sig.signal || 'certificate signal'))
      .join(', ');
    attentionRequired.push(
      `Certificate intelligence flagged ${certSignals.length} suspicious signal${certSignals.length !== 1 ? 's' : ''}: ${sigPreview}.`
    );
  }
  if (saasTotal > 0) {
    attentionRequired.push(
      `${saasTotal} SaaS portal${saasTotal !== 1 ? 's' : ''} exposed — login or admin access may be reachable externally.`
    );
  }
  if ((vendorRiskMap.medium ?? 0) > 0) {
    attentionRequired.push(
      `${vendorRiskMap.medium} medium-risk vendor${(vendorRiskMap.medium ?? 0) !== 1 ? 's' : ''} detected in the supply chain.`
    );
  }
  if (brandMedRisk > 0 && brandHighRisk === 0) {
    attentionRequired.push(
      `${brandMedRisk} medium-risk typosquat domain${brandMedRisk !== 1 ? 's' : ''} found actively resolving.`
    );
  }

  // ── Urgent ────────────────────────────────────────────────────────────────
  if (criticalFindings > 0) {
    urgent.push(
      `${criticalFindings} critical finding${criticalFindings !== 1 ? 's' : ''} require immediate remediation.`
    );
  }
  if (highFindings > 0) {
    urgent.push(
      `${highFindings} high-severity finding${highFindings !== 1 ? 's' : ''} should be addressed soon.`
    );
  }
  if (brandHighRisk > 0) {
    urgent.push(
      `${brandHighRisk} high-risk brand impersonation domain${brandHighRisk !== 1 ? 's' : ''} ${brandHighRisk === 1 ? 'is' : 'are'} actively resolving — phishing risk.`
    );
  }
  if (adminTotal > 0) {
    urgent.push(
      `${adminTotal} admin surface${adminTotal !== 1 ? 's' : ''} exposed to the internet — management interfaces should not be publicly accessible.`
    );
  }
  if ((vendorRiskMap.high ?? 0) > 0) {
    urgent.push(
      `${vendorRiskMap.high} high-risk vendor${(vendorRiskMap.high ?? 0) !== 1 ? 's' : ''} detected — supply chain exposure requires review.`
    );
  }
  if (certRiskLevel === 'critical') {
    const certDetail = certDaysLeft !== null
      ? `expires in ${certDaysLeft} day${certDaysLeft !== 1 ? 's' : ''}`
      : 'suspicious signals detected';
    urgent.push(`Certificate is at critical risk — ${certDetail}.`);
  }

  // ── Security Posture Breakdown ────────────────────────────────────────────
  const security_posture = computeSecurityPosture(
    // Pass a partial scorecard-like object — only the fields computeSecurityPosture reads
    {
      last_scanned_domain: latestScan?.domain ?? null,
      new_assets_30d:      newAssets30d,
      vendor_risk:         { high: vendorRiskMap.high ?? 0, medium: vendorRiskMap.medium ?? 0, low: vendorRiskMap.low ?? 0 },
      third_party_assets:  tpaTotal,
      saas_exposures:      saasTotal,
      admin_surfaces:      adminTotal,
      brand_risks:         { high: brandHighRisk, medium: brandMedRisk, low: brandRiskMap.low ?? 0 },
      certificate_risks:   { risk_level: certRiskLevel, signals: certSignals.length, days_until_expiry: certDaysLeft },
    },
    report
  );

  // ── Final scorecard object ─────────────────────────────────────────────────
  return {
    workspace_id:        wsId,
    workspace_name:      wsName,
    security_score:      latestScan?.score  ?? null,
    risk_rating:         latestScan?.rating ?? 'unknown',
    last_scan_at:        latestScan?.created_at ?? null,
    last_scanned_domain: latestScan?.domain     ?? null,
    attack_surface_size: activeAssets,
    active_assets:       activeAssets,
    new_assets_30d:      newAssets30d,
    vendors_detected:    vendorsActive,
    vendor_risk: {
      high:   vendorRiskMap.high   ?? 0,
      medium: vendorRiskMap.medium ?? 0,
      low:    vendorRiskMap.low    ?? 0,
    },
    third_party_assets: tpaTotal,
    saas_exposures:     saasTotal,
    admin_surfaces:     adminTotal,
    brand_risks: {
      total:  brandTotal,
      active: activeBrands,
      high:   brandHighRisk,
      medium: brandMedRisk,
      low:    brandRiskMap.low ?? 0,
    },
    certificate_risks: {
      risk_level:        certRiskLevel,
      signals:           certSignals.length,
      days_until_expiry: certDaysLeft,
    },
    critical_findings: criticalFindings,
    high_findings:     highFindings,
    medium_findings:   mediumFindings,
    low_findings:      lowFindings,
    asset_events_30d:  events30d,
    executive_summary: {
      good,
      attention_required: attentionRequired,
      urgent,
    },
    top_recommendations: topRemediation,
    security_posture,
  };
}

// ── Vendor Inventory Upsert ───────────────────────────────────────────────────
//
// Persists the vendor_risk module output to workspace_vendors (D1).
// Called after Phase 7e and after workspace lookup is available.
// All errors are non-fatal — failure here does not affect scan status.

/**
 * upsertVendorInventory
 *
 * For each workspace that owns `domainId`:
 *   1. Upsert active vendors from `vendorRisk.vendors` into workspace_vendors.
 *      - INSERT OR IGNORE to preserve first_seen.
 *      - UPDATE last_seen + status='active' + updated_at on every upsert.
 *   2. Mark any workspace_vendors rows NOT in the current detected set as inactive.
 */
async function upsertVendorInventory(domainId, vendorRisk, env) {
  if (!vendorRisk?.detected || !vendorRisk.vendors?.length) return;

  // Find all workspaces that own this domain
  let wsRows;
  try {
    const r = await env.cybermeters_db
      .prepare("SELECT workspace_id FROM workspace_domains WHERE domain_id = ?")
      .bind(domainId)
      .all();
    wsRows = r.results || [];
  } catch {
    return;
  }
  if (wsRows.length === 0) return;

  const now = new Date().toISOString();
  const detectedNames = vendorRisk.vendors.map((v) => v.name);

  for (const { workspace_id } of wsRows) {
    // Upsert each detected vendor
    for (const v of vendorRisk.vendors) {
      try {
        const id = createId("vendor");
        const evidenceJson = JSON.stringify(v.evidence || []);

        // INSERT OR IGNORE preserves first_seen for existing rows
        await env.cybermeters_db
          .prepare(
            `INSERT OR IGNORE INTO workspace_vendors
               (id, workspace_id, vendor_name, category, source, evidence,
                confidence, risk_level, first_seen, last_seen, status,
                created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?)`
          )
          .bind(
            id, workspace_id, v.name, v.category, v.source, evidenceJson,
            v.confidence, v.risk_level, now, now, now, now
          )
          .run();

        // UPDATE existing row — refresh last_seen, evidence, confidence, status
        await env.cybermeters_db
          .prepare(
            `UPDATE workspace_vendors
             SET last_seen = ?, evidence = ?, confidence = ?, risk_level = ?,
                 status = 'active', updated_at = ?
             WHERE workspace_id = ? AND vendor_name = ? AND category = ?`
          )
          .bind(
            now, evidenceJson, v.confidence, v.risk_level, now,
            workspace_id, v.name, v.category
          )
          .run();
      } catch { /* non-fatal per-vendor failure */ }
    }

    // Mark previously-detected vendors that were not seen this scan as inactive.
    // Only touch rows in this workspace — preserve other workspaces.
    if (detectedNames.length > 0) {
      try {
        // D1 does not support parameterised IN lists of variable length, so
        // we build a literal list. Values are vendor names (strings) — safe to
        // embed as SQL string literals after escaping single-quotes.
        const escaped = detectedNames.map((n) => `'${n.replace(/'/g, "''")}'`).join(", ");
        await env.cybermeters_db
          .prepare(
            `UPDATE workspace_vendors
             SET status = 'inactive', updated_at = ?
             WHERE workspace_id = ? AND status = 'active'
               AND source_module = 'vendor_risk'
               AND vendor_name NOT IN (${escaped})`
          )
          .bind(now, workspace_id)
          .run();
      } catch { /* non-fatal */ }
    }
  }
}

/**
 * sendAssetChangeAlert
 *
 * Called once per scan after upsertAssetInventory completes.
 * Looks up all workspaces that own this domain, queries asset_events for this
 * scan, builds a grouped summary, and sends one email per workspace.
 *
 * Dedup: INSERT OR IGNORE into asset_alert_records prevents re-sends.
 * The whole function is non-fatal — any error is swallowed.
 */
async function sendAssetChangeAlert(domainId, domain, scanId, env) {
  try {
    // Find all workspaces that own this domain
    const wsResult = await env.cybermeters_db
      .prepare(`SELECT workspace_id FROM workspace_domains WHERE domain_id = ?`)
      .bind(domainId)
      .all();
    const workspaceIds = (wsResult.results || []).map((r) => r.workspace_id);
    if (workspaceIds.length === 0) return;

    // Fetch all asset events for this scan (across all workspaces in one query)
    const eventsResult = await env.cybermeters_db
      .prepare(
        `SELECT workspace_id, event_type, hostname
         FROM asset_events
         WHERE scan_id = ?`
      )
      .bind(scanId)
      .all();
    const allEvents = eventsResult.results || [];

    // Group events by workspace_id
    const byWorkspace = new Map();
    for (const ev of allEvents) {
      if (!byWorkspace.has(ev.workspace_id)) byWorkspace.set(ev.workspace_id, []);
      byWorkspace.get(ev.workspace_id).push(ev);
    }

    for (const workspace_id of workspaceIds) {
      try {
        const events = byWorkspace.get(workspace_id) || [];
        if (events.length === 0) continue;

        // Count events by type
        const counts = {};
        const hostnamesByType = {};
        for (const ev of events) {
          if (!ASSET_ALERT_EVENTS.has(ev.event_type)) continue;
          counts[ev.event_type] = (counts[ev.event_type] || 0) + 1;
          if (ev.hostname) {
            if (!hostnamesByType[ev.event_type]) hostnamesByType[ev.event_type] = [];
            hostnamesByType[ev.event_type].push(ev.hostname);
          }
        }

        if (!assetAlertWorthy(counts)) continue;

        const severity = assetAlertSeverity(counts);

        // Collect top hostnames — prioritise high-severity event types
        const topHostnames = [
          ...(hostnamesByType.takeover_risk_detected || []),
          ...(hostnamesByType.new_asset_discovered   || []),
          ...(hostnamesByType.certificate_new_san_detected || []),
          ...(hostnamesByType.certificate_new_detected || []),
          ...(hostnamesByType.certificate_new_issuer_detected || []),
          ...(hostnamesByType.cloud_storage_detected || []),
          ...(hostnamesByType.wildcard_dns_detected  || []),
          ...(hostnamesByType.asset_reappeared       || []),
        ].filter((v, i, a) => a.indexOf(v) === i).slice(0, 5);

        // Dedup: INSERT OR IGNORE — if this (workspace_id, scan_id) already has a
        // record the insert is silently skipped and we don't send the email again.
        const now    = new Date().toISOString();
        const recId  = createId("aar");
        const insert = await env.cybermeters_db
          .prepare(
            `INSERT OR IGNORE INTO asset_alert_records
               (id, workspace_id, scan_id, domain, severity, event_counts, top_hostnames, sent_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
          )
          .bind(
            recId,
            workspace_id,
            scanId,
            domain,
            severity,
            JSON.stringify(counts),
            JSON.stringify(topHostnames),
            now
          )
          .run();

        // meta.changes === 0 means the row already existed — skip email
        if (!insert.meta || insert.meta.changes === 0) continue;

        // Build + send email
        const frontendOrigin = getEmailFrontendOrigin(env);
        const { subject, text, html } = buildAssetAlertEmail(
          domain,
          workspace_id,
          scanId,
          counts,
          topHostnames,
          severity,
          frontendOrigin ? `${frontendOrigin}/assets` : null,
        );
        const delivery = await sendAlertEmail(subject, text, html, env, "ALERT_EMAIL_FROM");
        if (delivery.sent) {
          console.log("[asset-alert] accepted", JSON.stringify({ workspace_id, scanId, severity, counts, provider_id: delivery.provider_id || null }));
        } else {
          console.error("[asset-alert] delivery failed", JSON.stringify({ workspace_id, scanId, reason: delivery.reason }));
        }
      } catch (wsErr) {
        console.error("[asset-alert] workspace error", workspace_id, wsErr?.message);
      }
    }
  } catch (err) {
    console.error("[asset-alert] failed:", err?.message);
  }
}

// ── Email Alert Engine ────────────────────────────────────────────────────────

/**
 * Inspect historical_changes and findings from a completed scheduled scan.
 * Returns an array of trigger objects when an alert is warranted, or null
 * when nothing notable changed (or when there is no previous scan to compare).
 *
 * Alert conditions:
 *   • Score dropped by 10+ points
 *   • One or more new subdomain takeover risks
 *   • One or more new reachable exposed assets
 *   • One or more new findings with severity 'high' or 'critical'
 */
function shouldSendAlert(historicalChanges) {
  if (!historicalChanges || !historicalChanges.has_previous) return null;

  const triggers = [];

  if (historicalChanges.score_change != null && historicalChanges.score_change <= -10) {
    triggers.push({
      type:   "score_drop",
      detail: `Score dropped ${historicalChanges.score_change} points ` +
              `(${historicalChanges.previous_score} → ${historicalChanges.current_score})`,
    });
  }

  if (historicalChanges.new_takeover_risks?.length > 0) {
    triggers.push({
      type:  "takeover_risk",
      count: historicalChanges.new_takeover_risks.length,
      hosts: historicalChanges.new_takeover_risks.map((r) => r.host),
    });
  }

  if (historicalChanges.new_exposed_assets?.length > 0) {
    triggers.push({
      type:  "exposed_asset",
      count: historicalChanges.new_exposed_assets.length,
      hosts: historicalChanges.new_exposed_assets.map((a) => a.host),
    });
  }

  const criticalNew = (historicalChanges.new_findings || []).filter(
    (f) => f.severity === "high" || f.severity === "critical"
  );
  if (criticalNew.length > 0) {
    triggers.push({
      type:     "new_finding",
      findings: criticalNew.map((f) => ({ title: f.title, severity: f.severity })),
    });
  }

  return triggers.length > 0 ? triggers : null;
}

/**
 * Build a plain-text and HTML email body for a set of alert triggers.
 */
function buildAlertEmail(domain, scanId, triggers) {
  const count   = triggers.length;
  const subject = `⚠ CyberMeters Alert: ${domain} — ` +
                  `${count} issue${count !== 1 ? "s" : ""} detected`;

  // Plain-text summary lines
  const lines = [];
  for (const t of triggers) {
    if (t.type === "score_drop") {
      lines.push(`Score drop: ${t.detail}`);
    } else if (t.type === "takeover_risk") {
      lines.push(
        `${t.count} new subdomain takeover risk${t.count !== 1 ? "s" : ""}: ` +
        t.hosts.join(", ")
      );
    } else if (t.type === "exposed_asset") {
      lines.push(
        `${t.count} new exposed asset${t.count !== 1 ? "s" : ""}: ` +
        t.hosts.join(", ")
      );
    } else if (t.type === "new_finding") {
      const titles = t.findings.map((f) => `${f.severity}: ${f.title}`).join("; ");
      lines.push(
        `${t.findings.length} new high/critical finding${t.findings.length !== 1 ? "s" : ""}: ` +
        titles
      );
    }
  }

  const reportUrl = `https://cybermeters.pages.dev/scans/${scanId}`;

  const text =
    `CyberMeters scheduled scan alert for ${domain}\n\n` +
    lines.map((l) => `• ${l}`).join("\n") +
    `\n\nView full report: ${reportUrl}`;

  const listItems = lines
    .map((l) => `<li style="margin-bottom:8px">${l}</li>`)
    .join("\n      ");

  const html = `<!DOCTYPE html>
<html lang="en">
<body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111;max-width:600px;margin:0 auto;padding:24px;">
  <div style="border-left:4px solid #00876A;padding-left:16px;margin-bottom:20px;">
    <h2 style="margin:0 0 4px;color:#00876A;font-size:18px;">CyberMeters Alert</h2>
    <p style="margin:0;color:#555;font-size:14px;">
      Scheduled scan completed for <strong>${domain}</strong>
    </p>
  </div>
  <ul style="padding-left:20px;line-height:1.7;font-size:14px;color:#333;">
      ${listItems}
  </ul>
  <p style="margin-top:24px;">
    <a href="${reportUrl}"
       style="background:#00876A;color:white;padding:10px 20px;border-radius:8px;
              text-decoration:none;font-size:14px;font-weight:600;display:inline-block;">
      View Full Report
    </a>
  </p>
  <hr style="border:none;border-top:1px solid #eee;margin:28px 0;" />
  <p style="font-size:12px;color:#999;margin:0;">
    CyberMeters &mdash; Attack Surface Management<br>
    This alert fired because a scheduled scan detected security-relevant changes.
  </p>
</body>
</html>`;

  return { subject, text, html };
}

const EMAIL_SENDER_KEYS = new Set(["ALERT_EMAIL_FROM", "SAFE_EMAIL_FROM", "HELLO_EMAIL_FROM"]);

function normalizeEmailRecipients(toEmails) {
  const values = Array.isArray(toEmails) ? toEmails : typeof toEmails === "string" ? [toEmails] : [];
  const unique = new Map();
  for (const value of values) {
    const email = String(value || "").trim().toLowerCase();
    if (isValidEmail(email)) unique.set(email, email);
  }
  return [...unique.values()];
}

function resolveEmailSender(env, fromKey) {
  if (!EMAIL_SENDER_KEYS.has(fromKey)) return null;
  const sender = String(env[fromKey] || "").trim().toLowerCase();
  return isValidEmail(sender) ? sender : null;
}

function getEmailFrontendOrigin(env) {
  const configured = env.FRONTEND_URL || env.APP_URL || env.ALLOWED_ORIGIN;
  try {
    const parsed = new URL(configured);
    return parsed.protocol === "https:" ? parsed.origin : null;
  } catch {
    return null;
  }
}

function emailDeliveryLog(level, details) {
  const payload = JSON.stringify({ service: "resend", ...details });
  if (level === "error") console.error("[email-delivery]", payload);
  else console.log("[email-delivery]", payload);
}

async function deliverEmail(subject, text, html, env, fromKey, toEmails) {
  const to = normalizeEmailRecipients(toEmails);
  const from = resolveEmailSender(env, fromKey);
  const safeSubject = String(subject || "").replace(/[\r\n]+/g, " ").trim();
  const context = { from_key: fromKey, recipient_count: to.length };

  if (!env.RESEND_API_KEY) {
    emailDeliveryLog("error", { ...context, outcome: "skipped", reason: "missing_api_key" });
    return { sent: false, reason: "missing_api_key" };
  }
  if (!from) {
    emailDeliveryLog("error", { ...context, outcome: "skipped", reason: "invalid_sender" });
    return { sent: false, reason: "invalid_sender" };
  }
  if (to.length === 0) {
    emailDeliveryLog("error", { ...context, outcome: "skipped", reason: "no_valid_recipients" });
    return { sent: false, reason: "no_valid_recipients" };
  }
  if (!safeSubject || !String(text || "").trim() || !String(html || "").trim()) {
    emailDeliveryLog("error", { ...context, outcome: "skipped", reason: "invalid_content" });
    return { sent: false, reason: "invalid_content" };
  }

  try {
    const response = await fetch("https://api.resend.com/emails", {
      method:  "POST",
      headers: {
        "Content-Type":  "application/json",
        "Authorization": `Bearer ${env.RESEND_API_KEY}`,
      },
      body: JSON.stringify({ from, to, subject: safeSubject, text, html }),
      signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) {
      emailDeliveryLog("error", { ...context, outcome: "failed", reason: "provider_rejected", status: response.status });
      return { sent: false, reason: "provider_rejected", status: response.status };
    }
    let providerId = null;
    try { providerId = (await response.json())?.id || null; } catch { /* response ID is optional */ }
    emailDeliveryLog("info", { ...context, outcome: "accepted", provider_id: providerId });
    return { sent: true, provider_id: providerId };
  } catch (error) {
    emailDeliveryLog("error", {
      ...context,
      outcome: "failed",
      reason: error?.name === "TimeoutError" ? "timeout" : "network_error",
    });
    return { sent: false, reason: error?.name === "TimeoutError" ? "timeout" : "network_error" };
  }
}

async function sendAlertEmail(subject, text, html, env, fromKey = "ALERT_EMAIL_FROM", toEmails = null) {
  const to = Array.isArray(toEmails) && toEmails.length > 0
    ? toEmails
    : typeof toEmails === "string" && toEmails.trim()
      ? [toEmails]
      : [env.ALERT_EMAIL_TO];
  return deliverEmail(subject, text, html, env, fromKey, to);
}

/**
 * sendCustomerEmail — strict variant for user-facing emails.
 * Unlike sendAlertEmail, this NEVER falls back to env.ALERT_EMAIL_TO.
 * If toEmails is empty or invalid, returns a failed delivery result without sending.
 * Use this for: password reset, workspace alert notifications.
 */
async function sendCustomerEmail(subject, text, html, env, fromKey = "ALERT_EMAIL_FROM", toEmails = null) {
  const to = Array.isArray(toEmails) ? toEmails : [];
  return deliverEmail(subject, text, html, env, fromKey, to);
}

// ─────────────────────────────────────────────────────────────────────────────
// Dedicated alert functions — each fires via the appropriate sender address
// and is swallowed on error so the scan pipeline is never interrupted.
// ─────────────────────────────────────────────────────────────────────────────

async function getWorkspaceAlertRecipients(workspaceId, env) {
  try {
    const result = await env.cybermeters_db
      .prepare(
        `SELECT u.email
         FROM workspace_members wm
         JOIN users u ON u.id = wm.user_id
         WHERE wm.workspace_id = ? AND wm.role IN ('owner', 'admin')`
      )
      .bind(workspaceId)
      .all();
    
    let emails = (result.results || []).map(r => r.email).filter(Boolean);
    
    const wsRow = await env.cybermeters_db
      .prepare("SELECT owner_user_id FROM workspaces WHERE id = ?")
      .bind(workspaceId)
      .first();
    if (wsRow?.owner_user_id) {
      const ownerUser = await env.cybermeters_db
        .prepare("SELECT email FROM users WHERE id = ?")
        .bind(wsRow.owner_user_id)
        .first();
      if (ownerUser?.email && !emails.includes(ownerUser.email)) {
        emails.push(ownerUser.email);
      }
    }
    
    return emails;
  } catch (err) {
    return [];
  }
}

async function isAlertDuplicate(env, workspaceId, alertType, relatedEntity, checkThresholdFn = null) {
  try {
    const query = await env.cybermeters_db
      .prepare(
        `SELECT metadata_json, created_at FROM notification_events
         WHERE workspace_id = ? AND type = ?
         ORDER BY created_at DESC`
      )
      .bind(workspaceId, alertType)
      .all();
    
    const rows = query.results || [];
    const oneDayAgo = Date.now() - 24 * 60 * 60 * 1000;
    
    for (const row of rows) {
      let meta = {};
      try {
        meta = JSON.parse(row.metadata_json || '{}');
      } catch (e) {
        continue;
      }
      
      if (meta.related_entity === relatedEntity) {
        const rowDateStr = row.created_at.includes('Z') || row.created_at.includes('+')
          ? row.created_at
          : row.created_at.replace(' ', 'T') + 'Z';
        const createdAtTime = new Date(rowDateStr).getTime();
        
        if (createdAtTime >= oneDayAgo) {
          return true;
        }
        
        if (checkThresholdFn) {
          const thresholdDup = checkThresholdFn(meta);
          if (thresholdDup) {
            return true;
          }
        }
      }
    }
    return false;
  } catch (err) {
    return false;
  }
}

function escapeEmailHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function formatAlertEmail({ workspaceName, domain, whatChanged, recommendation, link }) {
  const text = `CyberMeters Alert

Workspace: ${workspaceName}
Affected Domain: ${domain || "N/A"}

What Changed:
${whatChanged}

Recommended Next Action:
${recommendation}

View Dashboard/Report:
${link || "Open CyberMeters to review this alert."}

--
CyberMeters — Attack Surface Management
This is an automated alert from your CyberMeters Platform.`;

  const html = `<!DOCTYPE html>
<html>
<body style="font-family: sans-serif; color: #111; max-width: 600px; margin: 0 auto; padding: 20px; line-height: 1.5;">
  <h2 style="color: #00876A;">CyberMeters Alert</h2>
  <table style="width: 100%; border-collapse: collapse; margin-bottom: 20px;">
    <tr>
      <td style="padding: 6px 0; font-weight: bold; width: 150px;">Workspace:</td>
      <td>${escapeEmailHtml(workspaceName)}</td>
    </tr>
    ${domain ? `<tr>
      <td style="padding: 6px 0; font-weight: bold;">Affected Domain:</td>
      <td>${escapeEmailHtml(domain)}</td>
    </tr>` : ''}
  </table>
  
  <div style="background: #F9FAFB; border-left: 4px solid #F59E0B; padding: 15px; margin-bottom: 20px;">
    <h4 style="margin: 0 0 8px 0; color: #374151;">What Changed:</h4>
    <p style="margin: 0; color: #4B5563; white-space: pre-wrap;">${escapeEmailHtml(whatChanged)}</p>
  </div>

  <div style="margin-bottom: 25px;">
    <h4 style="margin: 0 0 8px 0; color: #374151;">Recommended Next Action:</h4>
    <p style="margin: 0; color: #4B5563;">${escapeEmailHtml(recommendation)}</p>
  </div>

  ${link ? `<p style="margin-top: 20px;">
    <a href="${escapeEmailHtml(link)}" style="background: #00876A; color: white; padding: 10px 20px; border-radius: 6px; text-decoration: none; font-weight: bold; display: inline-block;">
      View Dashboard / Report
    </a>
  </p>` : ''}
  
  <hr style="border: none; border-top: 1px solid #E5E7EB; margin: 30px 0;" />
  <p style="font-size: 12px; color: #9CA3AF; margin: 0;">
    CyberMeters &mdash; Attack Surface Management<br>
    This alert was sent to workspace owners and admins.
  </p>
</body>
</html>`;

  return { text, html };
}

async function processAlertsForWorkspace(workspaceId, domainId, domain, scanId, currentScore, currentFindings, currentModules, startedAt, env) {
  try {
    const recipients = await getWorkspaceAlertRecipients(workspaceId, env);
    const wsRow = await env.cybermeters_db
      .prepare("SELECT name FROM workspaces WHERE id = ?")
      .bind(workspaceId)
      .first();
    const workspaceName = wsRow?.name || "Unknown Workspace";

    const triggerAlert = async ({ type, severity, title, message, relatedEntity, whatChanged, recommendation, fromKey = "ALERT_EMAIL_FROM", threshold = null }) => {
      const notifId = createId("notif");
      const metadata = { scan_id: scanId, domain, related_entity: relatedEntity };
      if (threshold !== null) {
        metadata.threshold = threshold;
      }
      
      let emailSentAt = null;
      if (recipients.length > 0) {
        const frontendOrigin = getEmailFrontendOrigin(env);
        const { text, html } = formatAlertEmail({
          workspaceName,
          domain,
          whatChanged,
          recommendation,
          link: frontendOrigin ? `${frontendOrigin}/scans/${encodeURIComponent(scanId)}` : null,
        });

        const delivery = await sendCustomerEmail(title, text, html, env, fromKey, recipients);
        metadata.email_delivery = delivery.sent
          ? { status: "accepted", provider_id: delivery.provider_id || null }
          : { status: "failed", reason: delivery.reason };
        if (delivery.sent) emailSentAt = new Date().toISOString();
      } else {
        metadata.email_delivery = { status: "skipped", reason: "no_recipients" };
      }

      await env.cybermeters_db
        .prepare(
          `INSERT INTO notification_events
             (id, workspace_id, type, severity, title, message, metadata_json, status, created_at, sent_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, 'unread', datetime('now'), ?)`
        )
        .bind(notifId, workspaceId, type, severity, title, message, JSON.stringify(metadata), emailSentAt)
        .run();
    };

    const hist = currentModules.historical_changes;
    const ssl = currentModules.ssl;

    // ── 1. Score Drop Alert ──
    if (hist?.has_previous && hist.score_change != null && hist.score_change <= -10) {
      const isDuplicate = await isAlertDuplicate(env, workspaceId, "score_drop", domain);
      if (!isDuplicate) {
        const scoreDiff = Math.abs(hist.score_change);
        await triggerAlert({
          type: "score_drop",
          severity: "high",
          title: `⚠ CyberMeters: ${domain} score dropped ${scoreDiff} points`,
          message: `Security score dropped from ${hist.previous_score} to ${hist.current_score} (-${scoreDiff} points).`,
          relatedEntity: domain,
          whatChanged: `The security score for ${domain} dropped by ${scoreDiff} points (${hist.previous_score} → ${hist.current_score}).`,
          recommendation: "A drop of this magnitude indicates new critical or high-severity findings. Review the full report immediately to resolve these issues.",
          fromKey: "ALERT_EMAIL_FROM"
        });
      }
    }

    // ── 2. New Critical/High Finding Alert ──
    if (hist?.has_previous && Array.isArray(hist.new_findings)) {
      const newCritHigh = hist.new_findings.filter(f => f.severity === "critical" || f.severity === "high");
      const nonDupNew = [];
      for (const f of newCritHigh) {
        const isDuplicate = await isAlertDuplicate(env, workspaceId, "new_finding", f.id);
        if (!isDuplicate) {
          nonDupNew.push(f);
        }
      }
      
      if (nonDupNew.length > 0) {
        const count = nonDupNew.length;
        const highestSeverity = nonDupNew.some(f => f.severity === "critical") ? "critical" : "high";
        const findingsListStr = nonDupNew.map(f => `• [${f.severity.toUpperCase()}] ${f.title}`).join("\n");
        
        await triggerAlert({
          type: "new_finding",
          severity: highestSeverity,
          title: `🚨 CyberMeters: ${count} new finding${count !== 1 ? "s" : ""} on ${domain}`,
          message: `Detected ${count} new high/critical severity finding${count !== 1 ? "s" : ""} requiring attention.`,
          relatedEntity: nonDupNew[0].id,
          whatChanged: `New high/critical security findings were discovered:\n${findingsListStr}`,
          recommendation: "Review the recommended remediation actions in the report and apply patches or configuration fixes.",
          fromKey: "ALERT_EMAIL_FROM"
        });
      }
    }

    // ── 3. Certificate Expiry Alert ──
    if (ssl?.cert_expiry_days != null && ssl.cert_expiry_days <= 14) {
      const currentThreshold = ssl.cert_expiry_days <= 7 ? 7 : 14;
      const isDuplicate = await isAlertDuplicate(env, workspaceId, "cert_expiry", domain, (meta) => {
        return (meta.threshold || 14) <= currentThreshold;
      });
      
      if (!isDuplicate) {
        const urgency = ssl.cert_expiry_days <= 7 ? "CRITICAL" : "URGENT";
        const barColor = ssl.cert_expiry_days <= 7 ? "critical" : "high";
        const expiryDateStr = ssl.cert_not_after 
          ? new Date(ssl.cert_not_after).toUTCString().slice(0, 22) + " UTC"
          : "unknown";
        
        await triggerAlert({
          type: "cert_expiry",
          severity: barColor,
          title: `[${urgency}] SSL certificate for ${domain} expires in ${ssl.cert_expiry_days} days`,
          message: `SSL certificate expires on ${expiryDateStr} (${ssl.cert_expiry_days} days remaining).`,
          relatedEntity: domain,
          whatChanged: `The SSL certificate for ${domain} is expiring in ${ssl.cert_expiry_days} days (Expiry: ${expiryDateStr}).`,
          recommendation: "An expired SSL certificate will cause browsers to block visitors to your site. Renew the certificate immediately.",
          fromKey: ssl.cert_expiry_days <= 14 ? "ALERT_EMAIL_FROM" : "SAFE_EMAIL_FROM",
          threshold: currentThreshold
        });
      }
    }

    // ── 4. New Vendor Discovered Alert ──
    if (currentModules.vendor_risk?.detected && currentModules.vendor_risk.vendors?.length) {
      const newVendorsQuery = await env.cybermeters_db
        .prepare(
          `SELECT id, vendor_name, category, risk_level
           FROM workspace_vendors
           WHERE workspace_id = ? AND first_seen >= ? AND status = 'active'`
        )
        .bind(workspaceId, startedAt)
        .all();
      const newVendors = newVendorsQuery.results || [];
      
      const nonDupVendors = [];
      for (const v of newVendors) {
        const isDuplicate = await isAlertDuplicate(env, workspaceId, "new_vendor", v.vendor_name);
        if (!isDuplicate) {
          nonDupVendors.push(v);
        }
      }
      
      if (nonDupVendors.length > 0) {
        const count = nonDupVendors.length;
        const vendorListStr = nonDupVendors.map(v => `• ${v.vendor_name} (${v.category || "General"})`).join("\n");
        await triggerAlert({
          type: "new_vendor",
          severity: "info",
          title: `🔍 CyberMeters: ${count} new vendor${count !== 1 ? "s" : ""} discovered for ${domain}`,
          message: `Discovered new active vendor${count !== 1 ? "s" : ""}: ${nonDupVendors.map(v => v.vendor_name).join(", ")}.`,
          relatedEntity: nonDupVendors[0].vendor_name,
          whatChanged: `New active vendor(s) detected on your attack surface:\n${vendorListStr}`,
          recommendation: "Review the vendor's security posture and ensure their compliance with security policies.",
          fromKey: "ALERT_EMAIL_FROM"
        });
      }
    }

    // ── 5. Supply Chain Risk Increase Alert ──
    const scHistoryQuery = await env.cybermeters_db
      .prepare(
        `SELECT resilience_score, concentration_level
         FROM workspace_supply_chain_history
         WHERE workspace_id = ?
         ORDER BY calculated_at DESC
         LIMIT 2`
      )
      .bind(workspaceId)
      .all();
    const scHistory = scHistoryQuery.results || [];
    if (scHistory.length === 2) {
      const curr = scHistory[0];
      const prev = scHistory[1];
      
      const resDropped = curr.resilience_score <= prev.resilience_score - 10;
      const levels = { 'low': 1, 'medium': 2, 'high': 3, 'critical': 4 };
      const conWorsened = (levels[curr.concentration_level] || 0) > (levels[prev.concentration_level] || 0);
      
      if (resDropped || conWorsened) {
        const isDuplicate = await isAlertDuplicate(env, workspaceId, "supply_chain_risk_increase", "supply_chain");
        if (!isDuplicate) {
          let changeDesc = "";
          if (resDropped) {
            changeDesc += `• Operational resilience score dropped from ${prev.resilience_score} to ${curr.resilience_score} (score drop: ${prev.resilience_score - curr.resilience_score} points)\n`;
          }
          if (conWorsened) {
            changeDesc += `• Third-party concentration risk level worsened from "${prev.concentration_level}" to "${curr.concentration_level}"\n`;
          }
          
          await triggerAlert({
            type: "supply_chain_risk_increase",
            severity: "high",
            title: `⚠️ CyberMeters Alert: Supply chain risk increased for workspace`,
            message: `Supply chain risk increase detected in workspace: ` +
              (resDropped ? `Resilience score dropped. ` : '') + (conWorsened ? `Concentration level worsened.` : ''),
            relatedEntity: "supply_chain",
            whatChanged: `Workspace supply chain security indicators have worsened:\n${changeDesc}`,
            recommendation: "Review your third-party vendor concentration and redundancy plans on the Supply Chain dashboard to mitigate systemic dependencies.",
            fromKey: "ALERT_EMAIL_FROM"
          });
        }
      }
    }

  } catch (err) {
    // Graceful error handling for alerts
  }
}

